TELEGRAM_TOKEN = os.environ.get("TELEGRAM_BOT_TOKEN", "").strip()
TELEGRAM_CHAT = os.environ.get("TELEGRAM_CHAT_ID", "").strip()
MODE = os.environ.get("SCREENER_MODE", CONFIG["MODE"]).strip().upper()
try:                                  # رأس المال من البيئة (اختياري)
    if os.environ.get("ACCOUNT_SIZE"):
        CONFIG["ACCOUNT_SIZE"] = float(os.environ["ACCOUNT_SIZE"])
except Exception:
    pass


def _apply_backtest_overrides(mode: str, env=None) -> list:
    """B1 (خطة الضبط 2026-07-03): تجاوز عتبات محدّدة عبر env — **في وضع BACKTEST
    حصريًا** (تجربة A/B لبوابتي M4/M2). الإنتاج محصّن تمامًا: أي وضع آخر يتجاهل
    المفاتيح (مقفول باختبار). يرجع قائمة ما طُبِّق للتوثيق برسالة الباكتيست."""
    applied = []
    if str(mode).strip().upper() != "BACKTEST":
        return applied
    env = env if env is not None else os.environ
    # (توسعة 2026-07-03 بعد تشخيص أسهم فيصل: السقف 97 والنافذة 20 والسيولة 200K
    #  أرقام هندسية غير موثّقة من فيصل وتخنق أسهمه — صارت قابلة للتجربة أيضًا.)
    for bt_env, cfg_key, cast in (
            ("BT_BASE_RANGE_MAX", "BASE_RANGE_MAX_PCT", float),
            ("BT_MIN_DROP_FLOOR", "MIN_DROP_FLOOR", float),
            ("BT_MAX_DROP_PCT", "MAX_DROP_PCT", float),
            ("BT_SPLIT_AWARE_M2", "BT_SPLIT_AWARE_M2", int),   # 🔬 M2 واعية للتقسيم
            ("BT_SPLIT_REF_M2", "BT_SPLIT_REF_M2", int),       # 🔬 M2 مرجع ما بعد التقسيم (فيصل)
            ("BT_SPLIT_AWARE_M4", "BT_SPLIT_AWARE_M4", int),   # 🔬 M4 واعية للتقسيم
            # 🚪 T-GATES (`gates_prereg.md`) — علما الذراعين الناقصين:
            # · G5 `BT_MIN_PRICE`: أرضية M1 ($1.5 هندسية) ⇒ أرضية فيصل المنصوصة $1.
            #   ⚠️ وهي نفسها العتبة التي تقرأها بوّابة «الإشارة الوهمية» point-in-time
            #   في `backtest_symbol` (‏`_pit_raw_price(...) < MIN_PRICE`) — مقصود:
            #   الذراع يخفض الأرضية **كلَّها** لا نصفَها.
            # · G6 `BT_M4_POST_SPLIT`: M4 على شموع ما بعد التقسيم حصرًا (بديل جذريّ).
            # كلاهما باكتيست حصريًّا — الإنتاج محصّن بقفل B1 (مقفول باختبارَي تسرّب).
            ("BT_MIN_PRICE", "MIN_PRICE", float),              # 🚪 G5: أرضية سعر M1
            ("BT_M4_POST_SPLIT", "BT_M4_POST_SPLIT", int),     # 🚪 G6: M4 ما بعد التقسيم
            ("BT_SPIKE_WINDOW", "PRIOR_SPIKE_WINDOW", int),
            ("BT_MIN_DOLLAR_VOL", "MIN_DOLLAR_VOL", float),
            # 🚧 T-FAILS (`fails_prereg.md`): سقف «نواقص التأكيد» — الفيتو الوحيد الذي
            # يقتل 85.14% ممّن يصله (968/1,137) **ولم يُختبَر ولا مرّة**، بينما الإشارة
            # التي يقوم عليها مقيسةٌ غير مميِّزة ثلاث مرّات (تقاعد A/B · 2025 مقلوبة ·
            # T-GATES). ⚠️ يمسّ **العضوية** ⇒ باكتيست حصريًّا، والإنتاج يبقى 3.
            ("BT_WATCH_MAX_FAILS", "WATCH_MAX_FAILS", int),
            # 🔬 تجربة الدخول المؤكَّد بالمسح (T1) — باكتيست حصريًا، منفصلة الدخول/الوقف
            ("BT_LIBERATION", "BT_LIBERATION", int),       # 🔓 T-LIBERATION
            # 🧱🕯️ T-STABILITY — **نصّ** لا عدد (الذراعُ اسمُها لا رقمُها)
            ("BT_STABILITY_GATE", "BT_STABILITY_GATE", str),
            ("BT_ANCHOR", "BT_ANCHOR", str),
            ("BT_LIB_WAIT", "BT_LIB_WAIT", int),
            # 🕯️ T-CANDLE (`candle_readiness_prereg.md`) — **كان غائبًا من هذا الجدول**
            # بينما `backtest.yml` يمرّره في البيئة ⇒ لا يصل CONFIG أبدًا ⇒ التشغيلة
            # تخرج خضراء بمُخرَجٍ فارغ (بصمة الـno-op). مقفول باختبار «كل مفتاح BT_*
            # في backtest.yml له صفّ في هذا الجدول» (P1-① 2026-07-30).
            ("BT_CANDLE", "BT_CANDLE", int),               # 🕯️ T-CANDLE
            ("BT_SWEEP_ENTRY", "BT_SWEEP_ENTRY", int),
            ("BT_SWEEP_STOP", "BT_SWEEP_STOP", int),
            ("BT_SWEEP_PCT", "BT_SWEEP_PCT", float),
            ("BT_SWEEP_STOP_MARGIN", "BT_SWEEP_STOP_MARGIN", float),
            ("BT_SWEEP_MIN_RR", "BT_SWEEP_MIN_RR", float),
            ("BT_SPREAD_PCT", "BT_SPREAD_PCT", float),    # 🔬 F-COST
            ("BT_POTENTIAL", "BT_POTENTIAL", int),        # 🏦 قوة البوت
            ("BT_FEATURES", "BT_FEATURES", int),          # 🔬 أعمدة تحليل point-in-time
            ("BT_SHORT", "BT_SHORT", int),                # 🕵️ T-SHORT: شورت FINRA المؤرَّخ
            # ⛔ T-STOP (`stop_sweep_prereg.md`): عمق الوقف تحت الدعم — «lo,hi» مثل
            # «13,15». الغرض: اختبار وقفٍ **خارج منطقة مسح السيولة** (فيصل ENPH:
            # «جميع أوامر الوقف تحت الدعم · الوقف عند المتداولين من 5-7%»). باكتيست
            # حصريًّا · الإنتاج يبقى (5,7) بقفل اختبار · لا يمسّ أي جذر.
            ("BT_STOP_PCT", "STOP_BELOW_LOW_PCT", "pair"),
            ("BT_PORTFOLIO", "BT_PORTFOLIO", int),
            ("BT_PORT_SIZE", "BT_PORT_SIZE", int),
            # 🔁 T-REPLAY10 (تسجيلها المسبق): حقول إعادة التشغيل الأمينة —
            # **تاريخ الخروج الفعليّ** (‏`P0-02`: تحرير الخانة بجلسات لا `ordinals`)
            # و`rr` (المحور الرابع في `rank_key`، لم يكن يُخزَّن قطّ). باكتيست حصريًّا.
            ("BT_REPLAY10", "BT_REPLAY10", int),
            ("BT_MIRROR", "BT_MIRROR", int),          # 🪞 T-MIRROR
            ("BT_CADENCE", "BT_CADENCE", int),        # ⏱️ T-CADENCE
            ("BT_LIBVOL", "BT_LIBVOL", int),          # 🔓💧 T-LIBVOL
            ("BT_DORMANT", "BT_DORMANT", int),        # 😴 T-DORMANT
            ("BT_ENVVALS", "BT_ENVVALS", int),
            ("BT_ACTVALS", "BT_ACTVALS", int),        # 🕵️ T-RANKER3
            # 🛑 إرجاعُ وقف الارتكاز إلى 7% لإعادة إنتاج ما نُشر قبل الاعتماد
            #    (سابقةُ `CAP15`: أداةُ القياس تُعيد المنشور بت-بت أو تُبطله).
            ("BT_PIVOT_STOP", "PIVOT_STOP_AT_LOW", int),
            ("BT_RAW_PRICE", "BT_RAW_PRICE", int)):        # 🕰️ point-in-time
        v = (env.get(bt_env) or "").strip()
        if not v:
            continue
        try:
            if cast == "pair":          # ⛔ T-STOP: «lo,hi» ⇒ tuple(float, float)
                a, b = (float(x) for x in v.replace(" ", "").split(",")[:2])
                if not (0 < a <= b < 100):
                    continue            # قيمة غير معقولة ⇒ تُتجاهَل (فاشل-آمن)
                CONFIG[cfg_key] = (a, b)
                applied.append(f"{cfg_key}=({a:g},{b:g})")
                continue
            CONFIG[cfg_key] = cast(float(v))
            applied.append(f"{cfg_key}={CONFIG[cfg_key]:g}")
        except ValueError:
            pass
    # 🎯 T-CORE5 (`core5_prereg.md`): علمٌ **مركَّب** يختبر فرضية المالك «الأربع عشرة
    # تطلب الكمال — وقد تكفي الخمس». يُسقط **الحواجز المشتقّة وM13/M14 فقط**، ويُبقي
    # بوّابات الهوية صارمة: MIN_PRICE · MIN_DROP_FLOOR · MAX_DROP_PCT ·
    # PRIOR_SPIKE_FLOOR · MIN_DOLLAR_VOL · RSI_OS_HARD (= «الخمس + أرضية RSI»).
    # ⚠️ يمسّ العضوية ⇒ باكتيست حصريًّا (هذي الدالّة لا تعمل إلا بوضع BACKTEST).
    if str((env.get("BT_CORE5") or "")).strip() not in ("", "0"):
        for _k, _v in (("WATCH_MAX_FAILS", 99), ("NEAR_PCT", 0.0), ("SCORE_MIN", 0.0),
                       ("MIN_RR_T1", 0.0), ("RSI_NOW_HARD", 100.0),
                       ("SHORT_GATE_MAX", 10 ** 12), ("FLOAT_GATE_MAX", 10 ** 15)):
            CONFIG[_k] = _v
        applied.append("CORE5=1")
    return applied


def _bt_stomped(applied, cfg) -> list:
    """🔴 أيُّ تجاوزاتِ باكتيستٍ **طُلبت ولم تنفُذ**؟ — دالّةٌ نقيّة (عرض/تشخيص).

    **العيبُ المقيس (‏`ceiling_prereg.md §⑧`، 2026-08-16):** الترتيبُ على مستوى
    الوحدة `_apply_backtest_overrides` (‏`:769`) ثم `apply_faisal_only` (‏`:945`)
    التي تنفّذ `cfg.update(ov)` ⇒ **ظرفُ الكاتالوج يدهس ستّةَ مفاتيحَ**
    (‏`MAX_DROP_PCT` · `MIN_DROP_FLOOR` · `BASE_RANGE_MAX_PCT` · `MIN_PRICE` ·
    `MIN_DOLLAR_VOL` · `WATCH_MAX_FAILS`) عند `FAISAL_ONLY=1` وهو الافتراض.
    وكان سطرُ «الإعدادات» يعلن «تجربة: MAX_DROP_PCT=99.5» **والنافذ 99.94998**
    ⇒ **بصمةُ no-op أخبثُ من `BT_CANDLE`**: هناك لا يُطبع شيء، وهنا يُطبع
    **تأكيدٌ كاذب** أن التجربة اشتغلت. مُستنسَخٌ بالتشغيل لا بالقراءة.

    تُرجع أسماءَ المدهوسة («‏المفتاح: طُلب X والنافذ Y») — و**فارغةٌ = كلُّها
    نفذت**. وغيرُ الرقميّ (‏`STOP_BELOW_LOW_PCT` زوجٌ · `CORE5=1` بلا مفتاح)
    **يُتخطّى ولا يُدَّعى** (تعذّرٌ ≠ مخالفة).

    🐞 **والمقارنةُ نسبيّةٌ لا مطلقة — عيبٌ في نسختي الأولى أمسكه ناقدٌ خصوميّ
    قبل أيّ تشغيلة:** `_apply_backtest_overrides` يسجّل بـ`f"{v:g}"` = **ستُّ
    خاناتٍ معنوية** ⇒ `99.94998260261913` تُسجَّل «‏99.95» والفرقُ `1.74e-05`
    **أكبرُ من `1e-9`** ⇒ الحارسُ كان **يصرخ «لم تنفُذ» على تجربةٍ نافذة** =
    حارسٌ يمنع الصحيح، وهو **قفلٌ مكسورٌ لا أشدّ**. والنسبيّةُ `1e-5` تسع دقّةَ
    `:g` وتبقى تكشف الدهسَ الحقيقيّ (‏99.5 مقابل 99.95 = ‏4.5e-3)."""
    out = []
    for item in (applied or []):
        key, _, want = str(item).partition("=")
        key, want = key.strip(), want.strip()
        if not key or key not in (cfg or {}):
            continue
        try:
            got, wnt = float(cfg[key]), float(want)
            if abs(got - wnt) <= 1e-5 * max(1.0, abs(got), abs(wnt)):
                continue
            out.append(f"{key}: طُلب {want} والنافذ {got:g}")
        except (TypeError, ValueError):
            continue
    return out


_BT_OVERRIDES = _apply_backtest_overrides(MODE)


# ══════════════════════════════════════════════════════════════════════════════
# 🥇 **معايير فيصل وحدها** — أمرُ المالك الصريح المتكرّر (2026-08-06)
# ══════════════════════════════════════════════════════════════════════════════
# «لازم نلتزم بمعايير فيصل فقط وهذي نجيبها **عن طريق الكتالوج**» ثم — بعد أن قدّمتُ
# قياسًا بدل تنفيذ — «**ابن الحد الادنى و اعتمد على بواباته فقط**».
#
# 🔴 **والسببُ مقيسٌ لا رأي:** من 55 بوّابةً في `FAISAL_SOURCE_LEDGER.md` **‏25.5% فقط
# بسندٍ فيصليٍّ حرفيّ**، و**أربعٌ من بوّابات الهويّة الخمس من عندنا** (‏M1 سعر $1.5
# وأرضيةُ فيصل المنصوصة **$1** · M2 سقف 97% · M4 قاعدة 40% · M5 سيولة $200 ألف)
# **ولا رقمَ فيصليٍّ حرفيٍّ واحد فيها.** والأثر: الفارزُ يقول «لا» في **‏99.8%** من
# الأيام على أسهم فيصل نفسها، والتقطَ **صفرًا** من 203 متحرّكًا (`additions_audit.md`
# · `faisal_only_result.md`).
#
# ✅ **والحدُّ الأدنى ليس اختراعًا — هو مقيسٌ من كاتالوجه:** `catalog_envelope.py`
# مشى **أسهمَ فيصل نفسها** في العشرين جلسةً **قبل** بدء انفجارها (مِرساة
# `explosion_onset` المصحَّحة) وأخرج حدَّ كلِّ معيارٍ من **أربعة عشر** ⟶
# `envelope_p90.json` (‏`P90` · 25 رمزًا · بصمة `4fb70bcc13e5` — صارت 14 معيارًا
# بعد فتح D11 بأمر المالك 2026-08-07: gain5/ma_above/gap_above_dist مقيسة).
# **وكلُّ معيارٍ مربوطٌ سلفًا بمفتاح بوّابتنا** في `catalog_envelope.CRITERIA`
# ⇒ الإحلالُ **مباشرٌ بلا ترجمةٍ يدوية**.
#
# 🔒 **ولهذا كان التنفيذُ بإحلال الأرقام لا بتفريع الفرز:** بنيةُ البوّابات تبقى
# كما هي **وأرقامُها تصير أرقامَه** ⇒ صفرُ مسٍّ بـ`scan_market`/`analyze_ticker`،
# ومسارٌ واحدٌ يخدم الفرزَ والفحصَ اليدويَّ معًا (قفل «الفحص اليدوي = الأساسي»).
def faisal_only_overrides(edges: dict) -> dict:
    """🥇 يترجم حوافَّ ظرف الكاتالوج إلى تعييناتِ `CONFIG` — **دالّة نقيّة**.

    المصدرُ الوحيد للربط `catalog_envelope.CRITERIA` (‏`(معيار، جهة، وصف، مفتاح)`)
    فلا تتفرّق خريطةٌ مكتوبةٌ بيدي عن خريطة الأداة. `both` ⟹ مفتاحان بـ`|`.
    الأنواعُ تُصان (`WATCH_MAX_FAILS`/`SCORE_MIN` صحيحان). حوافٌّ ناقصة ⟹ تُتخطّى
    (‏**لا تُخمَّن**) · وحوافٌّ فارغة ⟹ `{}` أي «لا تغيير» (والمُنادي يُبلّغ)."""
    try:
        from catalog_envelope import CRITERIA as _CR
    except Exception:                                            # noqa: BLE001
        return {}
    out = {}
    # `TF_MIN_REVERSALS` صحيحٌ كذلك (عدّاد فريمات 0-3) — أُضيف مع قياسه 2026-08-07
    _INTS = {"WATCH_MAX_FAILS", "SCORE_MIN", "TF_MIN_REVERSALS"}
    for name, side, _desc, keyspec in _CR:
        if name not in (edges or {}):
            continue
        val = edges[name]
        keys = str(keyspec).split("|")
        try:
            if side == "both":
                if len(keys) != 2 or not isinstance(val, (list, tuple)) or len(val) != 2:
                    continue
                out[keys[0]], out[keys[1]] = float(val[0]), float(val[1])
            else:
                if len(keys) != 1 or isinstance(val, (list, tuple)):
                    continue
                out[keys[0]] = int(round(float(val))) if keys[0] in _INTS else float(val)
        except (TypeError, ValueError):
            continue
    return out


# 🥇 **خريطةُ «المثالي» في النواقص اللينة ⟵ وسيطُ الكاتالوج** (‏`soft_median`).
# 🔴 **ولماذا الوسيطُ لا الحافّة:** الحدُّ الصلب **طرفٌ خارجيّ** بطبعه (‏P90 = آخرُ ما
#    احتمله أسهمُه)، أمّا «المثالي» فوصفٌ لـ**مركز** توزيعه ⇒ الوسيط. والأربعةُ أدناه
#    مقيسةٌ في الظرف أصلًا فلا رقمَ جديدٌ يُخترَع.
# ⚠️ **و`TF_MIN_REVERSALS` غيرُ مذكورٍ هنا عمدًا — لكنّ سببَه تبدّل (2026-08-07):**
#    كان «لا يقيسه الظرف»، والآن **يقيسه معيارًا صلبًا** (‏`tf_count` الخامس عشر في
#    `CRITERIA` بأمر المالك «سوها») ⇒ حدُّه من الكاتالوج عبر مسار الحوافّ الصلبة،
#    **ويبقى خارج مسار الوسيط اللين هذا** (لا «مثاليّ» نصّيّ له فلا وسيطَ يُخمَّن).
SOFT_MEDIAN_KEYS = {
    "best_spike": ("PRIOR_SPIKE_PCT", "lo"),
    "drop_pct": ("MIN_DROP_PCT", "lo"),      # نطاقٌ: الجانبُ الأدنى (نقصُ الهبوط)
    "rsi_min": ("RSI_OVERSOLD", "hi"),
    "rsi_now": ("RSI_MAX_NOW", "hi"),
}


def faisal_soft_overrides(soft: dict) -> dict:
    """🥇 يترجم **وسيطَ الكاتالوج** إلى عتبات «المثالي» — دالّةٌ نقيّة.

    النطاق (`drop_pct`) يُؤخذ **جانبُه الأدنى** لأن النقصَ اللين هناك «هبوطٌ أقلّ من
    المثالي». والمفقودُ/التالفُ **يُتخطّى ولا يُخمَّن** · و`{}` = لا تغيير."""
    out = {}
    for name, (key, side) in SOFT_MEDIAN_KEYS.items():
        val = (soft or {}).get(name)
        if val is None:
            continue
        try:
            out[key] = float(val[0] if isinstance(val, (list, tuple)) else val) \
                if side == "lo" or not isinstance(val, (list, tuple)) \
                else float(val[1])
        except (TypeError, ValueError, IndexError):
            continue
    return out


# 🥇🔴 **قرارُ المالك 2026-08-10 «اعتمد 120» — سقفُ عرض القاعدة (‏M4) يعلو الظرف.**
# سندُه `base2_result.md` (‏`T-BASE-2`، تسجيلٌ مسبق `62865c0` **قبل أيّ رقم**): ذراعُ
# `B120` استوفت الحرّاسَ الأربعة — المنفجرون المُسلَّمون (`d50`) المجمَّع **‏53 مقابل
# 53 = صفرُ كلفةٍ مقيسة** · أقصى نقصٍ سنويّ **‏18.2%** (الحدّ 20) · `R`/صفقة يتحسّن
# ‏+0.058 · **وترفض `LGHL`** (عرضُ قاعدته المقيس ‏160.8%) · وبـ**‏8,756** رفضةً مقابل
# **‏46,712** لـ`B40` (‏5.3× أرخص) بينما `B40` يُكلّف **‏22.6%** من التسليم.
# ⚠️ **والتحفّظُ منشورٌ مع القرار لا مكتومًا** (`base2_result.md §③`): الإشارةُ
# **تنقلب** (‏+25.0% · −18.2% · −9.1%) والتساوي تصنعه 2024 وحدها، فالمقيسُ **«لم
# يُكلّف» لا «ربّح»** — وهذي **تجربةُ كلفة**، ومعيارُها عدمُ التدهور لا التحسّن.
#
# 🥇 **ووسمُه `engineering` لا `faisal_*` — مُعلَنٌ صريحًا:** ‏120 **رقمُ قرارٍ** لا
# رقمَ كاتالوج (أرقامُ الكاتالوج للقاعدة: **‏475.2** بـ`P90` و**‏23,684.63** بـ`P100`
# النافذ) ⇒ فهو **استثناءٌ صريح** من «أرقامُ فيصل وحدها»، مدوَّنٌ في
# `FAISAL_SOURCE_LEDGER.md` بوسمه.
#
# 🔒 **ولماذا طبقةٌ *بعد* الظرف لا تعديلَ ملفِّ الحوافّ:** إعادةُ معايرة الظرف
# (‏`catalog_envelope.yml`) تُصدر `base_range` جديدًا **فتدهس القرار صامتةً** — وهو
# صنفُ «الانقلاب الصامت» بعينه. فتُطبَّق **آخرًا** فلا يُزيلها إصدارُ ظرفٍ جديد،
# **وتُطبَع باسمها** فيبقى الفارزُ مقروءًا لا صندوقًا أسود.
# ⚠️ **ولا تُطبَّق عند `FAISAL_ONLY=0`** (عمدًا): بوّابةُ البوت هناك **‏40** وهي
# **أشدُّ** من 120، ورفعُها كان **إرخاءَ** بوّابةٍ لم يطلب المالكُ إرخاءها (وقفلا
# `B3`/`C3` يحرسان الأربعين بحكمٍ مقيس).
OWNER_GATE_OVERRIDES = {"BASE_RANGE_MAX_PCT": 120.0}


def apply_faisal_only(cfg: dict = None, log_fn=None) -> dict:
    """🥇 يُحِلّ أرقامَ فيصل في `CONFIG`. يرجّع ما طُبِّق (‏`{}` = لم يُطبَّق شيء).

    🔒 **فاشلٌ-آمنٌ بصوتٍ عالٍ لا بصمت:** تعذّرُ الحوافّ ⟹ تبقى بوّاباتُنا **ويُبلَّغ**
    — لأن الصمتَ هنا يعني فرزًا بأرقامٍ لا يعرفها المالك. و**كلُّ رقمٍ يُطبَّق يُطبَع**
    فيبقى الفارزُ مقروءًا لا صندوقًا أسود."""
    cfg = CONFIG if cfg is None else cfg
    if not cfg.get("FAISAL_ONLY"):
        return {}
    try:
        import envelope_scan as _ev
        edges = _ev.load_edges()
        fp = _ev.edges_fingerprint(edges) if edges else ""
    except Exception as _e:                                      # noqa: BLE001
        (log_fn or print)(f"⛔ معايير فيصل: تعذّر تحميل الظرف ({type(_e).__name__}) "
                          "— **بوّاباتُ البوت تبقى** (لا فرزَ بأرقامٍ مجهولة).")
        return {}
    ov = faisal_only_overrides(edges)
    if not ov:
        (log_fn or print)("⛔ معايير فيصل: حوافُّ الظرف غير محمَّلة/غير صالحة — "
                          "**بوّاباتُ البوت تبقى**.")
        return {}
    # 🥇 وعتباتُ «المثالي» في النواقص اللينة من **وسيط** الكاتالوج (‏§`soft_median`).
    #    غيابُ الكتلة (ظرفٌ قديم) ⇒ تبقى عتباتُنا **ويُعلَن** — لا صمت.
    # 🔴 **مفتاحٌ متخيَّل أمسكتُه بالتشغيل لا بالقراءة:** كتبتُ أوّلًا
    #    `edges.get("soft_median")` — و`load_edges` **يُرجع الحوافَّ وحدها** ويضع كلَّ
    #    ما عداها تحت `_meta` (عقدُها الموثَّق: «تمريرٌ شامل لكل مفتاحٍ غير `edges`»)
    #    ⇒ كانت الوصلةُ **ميتةً** والرسالةُ تقول «لا وسيطَ في الظرف» **والملفُّ فيه**.
    _soft = faisal_soft_overrides(
        ((edges or {}).get("_meta") or {}).get("soft_median") or {})
    ov.update(_soft)
    # 🥇 و**قرارُ المالك يعلو الظرفَ — ويُطبَّق آخرًا حصرًا** (‏§`OWNER_GATE_OVERRIDES`)
    #    فلا يدهسه إصدارُ حوافَّ جديد. **والترويسةُ تُصرّح بعددِه** وإلّا صار رقمُ قرارٍ
    #    مدفونًا في قائمةٍ عنوانُها «معايير فيصل وحدها» = سطرُ عرضٍ يكذب.
    ov.update(OWNER_GATE_OVERRIDES)
    cfg.update(ov)
    _own = len(OWNER_GATE_OVERRIDES)
    (log_fn or print)(
        "🥇 **معايير فيصل وحدها** مُفعَّلة (أمر المالك) · بصمةُ الحوافّ "
        f"{fp[:12]} · طُبِّق {len(ov)} رقمًا"
        + (f" (منها **{_own}** بقرار المالك لا من الكاتالوج)" if _own else "")
        + ": " + " · ".join(f"{k}={v}" for k, v in sorted(ov.items())))
    (log_fn or print)(
        f"   ↳ ومنها **{len(_soft)}** عتبةَ «مثاليّ» من وسيط الكاتالوج"
        if _soft else
        "   ↳ ⚠️ **لا وسيطَ في الظرف** ⇒ عتباتُ «المثالي» تبقى من عندنا "
        "(شغّل `catalog_envelope.yml` لإصدارها).")
    if _own:
        (log_fn or print)(
            "   ↳ 🥇 **بقرار المالك** (وسمُ `engineering` — لا من الكاتالوج · "
            "سندُه `T-BASE-2`): "
            + " · ".join(f"{k}={v}"
                         for k, v in sorted(OWNER_GATE_OVERRIDES.items())))
    return ov


_FAISAL_ONLY_APPLIED = apply_faisal_only()

# نسخة منطق التحليل — تُختم في ملف القائمة. أي تعديل يمسّ الدخول/الوقف/الأهداف/
# المستويات → ارفع الرقم، فالبوت يعيد حساب القائمة كاملة تلقائياً في أول تشغيل
# (ضمان: القائمة دائمًا على آخر منطق، بلا انتظار يوم التجديد ولا تدخّل يدوي).
def _anchor_mode(bt, prod) -> str:
    """نقيّة: الوضعُ النافذ لمِرساة الدخول/الوقف (اعتماد B2 «1» 2026-08-14).

    `bt` (تجاوزُ القياس) يعلو: **"pivot" يجبر الأساسَ القديم** (يُرجع "") ·
    وقيمةٌ أخرى غيرُ فارغة تُقاس كما هي · والفراغُ يُسلِّم للإنتاج `prod`
    (‏`ANCHOR_MODE`). مقفولةٌ بقفلٍ **مفرِّق** (‏ADOPT3) لأن أوّلَ قفلٍ نصّيٍّ
    عليها نجت طفرتُه (وجد "pivot" في تعليقٍ — الفخُّ الخامس)."""
    bt = str(bt or "")
    if bt == "pivot":
        return ""
    return bt or str(prod or "")


