# 📅 قناة جانبية: آخر دعوة اجتماع مساهمين لكل رمز (نمط _REJECT_STATS) — تُلتقط في
# sec_recent_filings بنافذة أطول من نافذة العرض وتُستهلك في enrich → upcoming_events
_SEC_PROXY = {}
_PROXY_FORMS = ("DEF 14A", "DEFA14A", "DEFR14A", "PRE 14A", "PRER14A",
                "DEF 14C", "PRE 14C")

# 🆕 قناة جانبية ثانية: آخر **طرح جديد** لكل رمز — الحدث المؤسِّس الموازي للتقسيم عند
# فيصل (بطاقته: «MWC — **طرح جديد** تاريخ 14/5 · افتتاح 8.10 · أعلى 26.38»). نفس نمط
# `_SEC_PROXY`: يُلتقط داخل نداء `sec_recent_filings` القائم = **صفر نداء إضافي**.
_SEC_OFFERING = {}
_OFFERING_FORMS = ("424B1", "424B2", "424B3", "424B4", "424B5", "424B7",
                   "S-1", "S-1/A", "S-3", "S-3/A", "F-1", "F-1/A", "F-3",
                   "EFFECT")
# ⚖️ **تضييق حاسم (تدقيق خصومي 2026-07-27):** الحدث المؤسِّس = **نشرة نهائية لطرح
# سُعِّر فعلًا** فقط. `S-1/S-3/F-3/EFFECT/424B3` تسجيلات رفّية/تحديثات **روتينية** —
# لو عاملناها «حدثًا مؤسِّسًا» لأعادت ضبط مرجع الـ÷2 لتاريخ اعتباطي وأسقطت بوّابة «لم
# يصعد». تُلتقط للعرض/السياق فقط (`_SEC_OFFERING`) ولا تُنشئ setup.
_FOUNDING_OFFERING_FORMS = ("424B1", "424B4", "424B5")
_SEC_OFFERING_MAX = 400          # سقف حجم القناة (لا تضخّم غير محدود عبر التشغيلة)
_SEC_FOUNDING = {}               # النشرة النهائية فقط = الحدث المؤسِّس

# 📄 قناة جانبية ثالثة: إفصاحات Form 4 (تداول الداخليين) — فيصل يذكر شراء الداخليين
# **سببًا مباشرًا** للارتفاع («ارتفعت بسبب المدير اشتري كمية اسهم 1.7 مليون سهم» SVRE ·
# «اشترى الرئيس 12 الف سهم بسعر 1.37 دولار» BNKK). نلتقط الميتا مجانًا هنا، والتصنيف
# (شراء/بيع) يحتاج المستند فيُجلب لاحقًا بسقف صارم في `enrich` فقط.
_SEC_FORM4 = {}
_FORM4_MAX_KEEP = 8
_SEC_FORM4_MAX = 400             # سقف حجم القناة (لا تضخّم عبر التشغيلة)

_RANK = {"🔴": 0, "🟢": 1, "🟡": 2, "⚪": 3}


def classify_8k_items(items_str: str):
    """يحوّل سلسلة بنود 8-K إلى أهم بند مصنّف (أحمر ثم أخضر ثم أصفر)"""
    codes = [x.strip() for x in (items_str or "").split(",") if x.strip()]
    parsed = []
    for cd in codes:
        emoji, label = SEC_8K_ITEMS.get(cd, ("⚪", f"بند {cd}"))
        parsed.append((emoji, label, cd))
    meaningful = [p for p in parsed if p[0] != "⚪"]
    if not meaningful:
        return None
    meaningful.sort(key=lambda x: _RANK.get(x[0], 9))
    emoji, label, cd = meaningful[0]
    extra = f" (+{len(meaningful) - 1} بنود)" if len(meaningful) > 1 else ""
    return f"{emoji} 8-K بند {cd}: {label}{extra}"


def sec_recent_filings(sym: str):
    """إعلانات SEC الرسمية لآخر N يوم، مصنّفة 🟢/🔴/🟡.
    يرجع (قائمة سطور، حالة: ok / no_cik / error)"""
    out = []
    cik = sec_cik_map().get(sym.upper())
    if not cik:
        return out, "no_cik"
    try:
        url = f"https://data.sec.gov/submissions/CIK{cik:010d}.json"
        r = requests.get(url, headers=SEC_UA, timeout=40)
        r.raise_for_status()
        recent = ((r.json().get("filings") or {}).get("recent")) or {}
        forms = recent.get("form", []) or []
        dates = recent.get("filingDate", []) or []
        items_l = recent.get("items", []) or []
        accs = recent.get("accessionNumber", []) or []
        pdocs = recent.get("primaryDocument", []) or []
        cutoff = (dt.date.today()
                  - dt.timedelta(days=CONFIG["SEC_FILING_DAYS"])).isoformat()
        # 📅 نافذة أطول لالتقاط دعوة اجتماع المساهمين (الاجتماع يُعقد عادة بعد
        # شهر-شهرين من الدعوة، فنافذة العرض القصيرة تفوّته) — التقاط فقط، لا عرض.
        pcut = (dt.date.today()
                - dt.timedelta(days=CONFIG["PROXY_LOOKBACK_DAYS"])).isoformat()
        full = False
        for i in range(len(forms)):
            fdate = dates[i] if i < len(dates) else ""
            if fdate < pcut:
                break  # القائمة مرتبة من الأحدث للأقدم
            form = (forms[i] or "").strip()
            if form in _PROXY_FORMS and sym.upper() not in _SEC_PROXY:
                _SEC_PROXY[sym.upper()] = {"form": form, "date": fdate}
            # 🆕 الطرح الجديد (حدث مؤسِّس عند فيصل) — أحدث نموذج طرح فقط
            # ⚠️ **قناتان منفصلتان (تدقيق خصومي):** الواسعة للسياق فقط، و**المؤسِّسة**
            # للنشرة النهائية حصرًا. بقناة واحدة كان أحدثُ `S-3` روتيني **يحجب**
            # النشرة الحقيقية الأقدم فتموت الميزة، **ويُعرَض التسجيل الرفّي نفسه**
            # كأنه «طرح جديد — حدث مؤسِّس».
            if (form in _OFFERING_FORMS and sym.upper() not in _SEC_OFFERING
                    and len(_SEC_OFFERING) < _SEC_OFFERING_MAX):
                _SEC_OFFERING[sym.upper()] = {"form": form, "date": fdate}
            if (form in _FOUNDING_OFFERING_FORMS
                    and sym.upper() not in _SEC_FOUNDING
                    and len(_SEC_FOUNDING) < _SEC_OFFERING_MAX):
                _SEC_FOUNDING[sym.upper()] = {"form": form, "date": fdate}
            # 📄 Form 4 (تداول داخليين): نخزّن الميتا فقط (صفر نداء إضافي هنا)
            if form == "4" and (sym.upper() in _SEC_FORM4
                                or len(_SEC_FORM4) < _SEC_FORM4_MAX):
                _f4 = _SEC_FORM4.setdefault(sym.upper(), [])
                if len(_f4) < _FORM4_MAX_KEEP:
                    _f4.append({"date": fdate, "cik": cik,
                                "acc": (accs[i] if i < len(accs) else ""),
                                "doc": (pdocs[i] if i < len(pdocs) else "")})
            if fdate < cutoff or full:
                continue           # خارج نافذة العرض — نكمل لالتقاط الوكالة فقط
            line = None
            if form.startswith("8-K"):
                cls = classify_8k_items(items_l[i] if i < len(items_l) else "")
                if cls:
                    line = f"{cls} — {fdate}"
            else:
                fc = SEC_FORM_CLASS.get(form)
                if fc:
                    line = f"{fc[0]} {form}: {fc[1]} — {fdate}"
            if line:
                out.append(line)
            if len(out) >= CONFIG["SEC_MAX_SHOW"]:
                full = True
        return out, "ok"
    except Exception as e:
        log(f"⚠️ SEC {sym}: {e}")
        return out, "error"


_F4_FAILS = [0]                 # قاطع دائرة مستندات Form 4 (يُصفَّر كل enrich)
_OFF_FAILS = [0]                # قاطع دائرة مستقل لكشف الطرح الجديد
_F4_BUDGET = [0]                # سقف مستندات Form 4 لكل تشغيلة إثراء


def _parse_form4(xml: str):
    """📄 **محلّل Form 4 نقيّ** (بلا شبكة): يستخرج من XML الإفصاح مَن اشترى وكم وبأي سعر.
    فيصل يعامل شراء الداخليين **سببًا مباشرًا للارتفاع** («ارتفعت بسبب المدير اشترى 1.7
    مليون سهم» SVRE · «اشترى الرئيس 12 ألف سهم بسعر 1.37 دولار» BNKK).

    القراءة: `transactionCode` = **P** (شراء بالسوق المفتوح) مع
    `transactionAcquiredDisposedCode` = **A** ⇒ شراء حقيقي. نجمع كل صفقات الشراء.
    ⚠️ **حدّان يُصرَّح بهما (تدقيق خصومي):** (1) الرمز **A** وحده لا يكفي (المنح `A`
    والممارسة `M` تظهر «مكتسبة» بلا شراء نقدي) فنشترط `P` صراحةً. **هذا اختيارنا
    المحافظ لا نقلٌ عن فيصل** — فيصل لم يذكر رموز SEC قط؛ كلامه «اشترى الرئيس 12 ألف
    سهم بسعر 1.37» يوافق `P`، أما «المدير اشترى 1.7 مليون سهم» فقد يكون صفقة خاصة أو
    ممارسة أدوات تُبلَّغ برمز آخر أو في الجدول المشتقّ **الذي لا نقرأه**. (2) نقرأ
    `<nonDerivativeTransaction>` فقط. فالفراغ = «لم نجد شراءً ضمن ما فحصناه» لا نفي.
    يرجّع {"owner","title","shares","price","is_buy"} أو None. فاشل-آمن مطلق."""
    try:
        if not xml or "<" not in xml:
            return None
        low = xml
        codes = re.findall(r"<transactionCode>\s*([A-Z])\s*</transactionCode>", low)
        if "P" not in codes:
            return None
        shares, notional, sold = 0.0, 0.0, False

        def _inner(tag, blk):
            """قيمة عنصر **داخل حدوده هو** — يمنع تسرّب regex لعنصر لاحق (ثغرة تدقيق:
            كتلة بلا سعر كانت تلتقط رقم الحاشية التالية). None لو غاب أو تعذّر."""
            e = re.search(rf"<{tag}>(.*?)</{tag}>", blk, re.S)
            if not e:
                return None
            v = re.search(r"<value>\s*([0-9]*\.?[0-9]+)\s*</value>", e.group(1))
            return float(v.group(1)) if v else None
        # كل كتلة صفقة على حدة حتى لا نخلط كميات البيع بالشراء
        for blk in re.findall(r"<nonDerivativeTransaction>(.*?)</nonDerivativeTransaction>",
                              low, re.S):
            cd = re.search(r"<transactionCode>\s*([A-Z])\s*</transactionCode>", blk)
            code = cd.group(1) if cd else ""
            if code in ("S", "D"):
                sold = True
            if code != "P":
                continue
            if not re.search(r"<transactionAcquiredDisposedCode>.*?<value>\s*A\s*</value>",
                             blk, re.S):
                continue
            q = _inner("transactionShares", blk)
            px = _inner("transactionPricePerShare", blk)
            if q and q > 0:
                shares += q
                if px and px > 0:
                    notional += q * px      # متوسط **مرجَّح** لا حسابي
        if shares <= 0:
            return None
        prices = [notional / shares] if notional > 0 else []
        own = re.search(r"<rptOwnerName>\s*(.*?)\s*</rptOwnerName>", low, re.S)
        ttl = re.search(r"<officerTitle>\s*(.*?)\s*</officerTitle>", low, re.S)
        is_dir = re.search(r"<isDirector>\s*(1|true)\s*</isDirector>", low)
        title = (ttl.group(1).strip() if ttl else ("عضو مجلس إدارة" if is_dir else ""))
        return {"owner": _sanitize_name(own.group(1)) if own else "",
                "title": _sanitize_name(title), "shares": int(shares),
                "price": (round(prices[0], 4) if prices else None),
                "has_sales": bool(sold), "is_buy": True}
    except Exception:
        return None


def form4_insider_buys(sym: str, cap: int = 2, fetch=None):
    """📄 شراء الداخليين حديثًا (Form 4). يقرأ الميتا المُلتقطة مجانًا في
    `sec_recent_filings` (`_SEC_FORM4`) ثم يجلب **مستندَين على الأكثر** ويحلّلهما.
    فاشل-آمن مطلق (لا ميتا/شبكة/قاطع دائرة → []) · `fetch(url)` محقون للاختبار ·
    **لا يُنادى في مسار الفرز** (enrich بعد select_top فقط). عرض/سياق — لا بوّابة."""
    meta = _SEC_FORM4.pop(str(sym).upper(), None) or []
    if not meta or (fetch is None and (_F4_FAILS[0] >= 3 or _F4_BUDGET[0] <= 0)):
        return []
    out = []
    for m in meta[:max(0, int(cap))]:
        if fetch is None:
            if _F4_BUDGET[0] <= 0:      # 🔒 سقف مشترك للتشغيلة (نمط `_bor_budget`)
                break
            _F4_BUDGET[0] -= 1
        try:
            acc = str(m.get("acc") or "").replace("-", "")
            doc = str(m.get("doc") or "")
            cik = int(m.get("cik"))
        except (TypeError, ValueError):
            continue                     # ميتا تالفة ⇒ تخطَّ (فاشل-آمن مطلق)
        if not acc or not doc:
            continue
        # ⚠️ **إصلاح حاسم (تدقيق خصومي، مُثبَت على 614/614 إيداع حقيقي):** حقل
        # `primaryDocument` لنماذج الملكية يأتي **بسابقة عرض XSL** (`xslF345X03/…`)
        # وذلك المسار يعيد **HTML مُصيَّرًا** بلا وسوم XML ⇒ المحلّل يرجع None دائمًا
        # فتكون الميزة ميتة **وتستهلك الميزانية كاملةً صامتةً** (الردّ 200 فلا يُحسب
        # إخفاقًا ولا يقطع الدائرة). الملف الخام = الاسم نفسه بلا السابقة.
        url = f"https://www.sec.gov/Archives/edgar/data/{cik}/{acc}/{doc.split('/')[-1]}"
        try:
            if fetch is not None:
                txt = fetch(url) or ""
            else:
                rr = requests.get(url, headers=SEC_UA, timeout=20)
                txt = rr.text if rr.status_code == 200 else ""
                time.sleep(0.15)               # احترام حد SEC
            if not txt:
                _F4_FAILS[0] += 1
                continue
        except Exception:
            _F4_FAILS[0] += 1
            continue
        p = _parse_form4(txt)
        if p:
            p["date"] = m.get("date")
            out.append(p)
        elif "<transactionCode>" not in txt:
            # مستند وصل لكنه ليس XML الملكية (صفحة مُصيَّرة/خطأ) — إخفاق حقيقي يجب
            # أن يراه قاطع الدائرة، وإلا مات المسار بصمت كما كشف التدقيق.
            _F4_FAILS[0] += 1
    return out


def insider_buy_line(r) -> str:
    """📄 سطر «شراء داخلي» (عرض فقط، بلا علامات مقارنة). فارغ لو لا شراء."""
    buys = (r or {}).get("insider_buys") or []
    if not buys:
        return ""
    b = buys[0]
    who = " ".join(x for x in (b.get("title"), b.get("owner")) if x) or "داخلي"
    px = f" بسعر ${b['price']:g}" if b.get("price") else ""
    more = f" (و{len(buys) - 1} إفصاح آخر)" if len(buys) > 1 else ""
    mixed = " ⚠️ ومعه بيع بنفس الإفصاح" if b.get("has_sales") else ""
    return (f"📄 شراء داخلي: {esc(who)} اشترى {fmt_money(b.get('shares'))} سهم"
            f"{px} — {b.get('date') or ''}{more}{mixed}")


def _latest_event_date(r, today=None, max_age_days: int = 21):
    """أحدث **تاريخ حدث معلوم** للسهم (شراء داخلي · طرح جديد · دعوة اجتماع) — يغذّي
    قاعدة «خبره عدم قبوله». التواريخ نصّية ISO فالمقارنة النصّية كافية.
    ⚖️ **حدّ الحداثة إلزامي (تدقيق خصومي 2026-07-27):** بلا سقف عمر كان حدثٌ عمره
    شهران يُقارَن بالرقم الحرج **اليوم** فينتج تحذير «لم يُقبَل» دائمًا وكاذبًا. الحدث
    الأقدم من `max_age_days` يُهمَل. نقيّة · فاشلة-آمنة."""
    try:
        today = today or dt.date.today()
        floor = (today - dt.timedelta(days=int(max_age_days))).isoformat()
        cand = []
        for b in ((r or {}).get("insider_buys") or []):
            if b.get("date"):
                cand.append(str(b["date"])[:10])
        # (دعوة الجمعية `proxy_filing` **ليست خبرًا** يُقبَل أو يُرفَض — أُسقطت)
        for k in ("offering_event",):
            ev = (r or {}).get(k) or {}
            if isinstance(ev, dict) and ev.get("date"):
                cand.append(str(ev["date"])[:10])
        cand = [d for d in cand if floor <= d <= today.isoformat()]
        return max(cand) if cand else None
    except Exception:
        return None


def news_acceptance(df, event_date):
    """📉 **قاعدة فيصل «خبره عدم قبوله = هبوط»** (بطاقة MBRX: «عدم ثبات فوق 3.15 يرجع
    يختبر الدعوم · **خبره عدم قبوله = هبوط**»). تقرأ شمعة **يوم الخبر** (أو أول جلسة
    بعده) وتحكم: هل ثبت السهم فوق الرقم الحرج؟
    ⚠️ **المرجع من شمعة الحدث نفسها حصرًا** (تصحيح مراجعة خصومية 2026-07-27): كانت
    تقارن إغلاق يوم الحدث بـ**الرقم الحرج المحسوب اليوم** — فارق زمني يقلب الحكم بلا
    حدث جديد، وأسوأ: الرقم الحرج بنيويًّا أعلى من سعر اليوم، فـ«مقبول» ما كان ممكنًا
    إلا لسهم **هبط** ⇒ التحذير الهابط كان يشتعل لمن **ارتفع** (إشارة مقلوبة).
    الآن: القبول = إغلاق شمعة الحدث **فوق افتتاحها وفوق إغلاق الجلسة السابقة** — حكم
    مكتفٍ بذاته، ثابت زمنيًّا، ويقرأ حرفيًّا «هل قَبِل السوقُ الإعلانَ يومَه».
    يرجّع {"accepted","close","ref","kind","date"} أو None (لا شمعة/تاريخ تالف).
    نقيّة · فاشلة-آمنة · **بلا نظر مستقبلي** (لا تنظر أبعد من شمعة الحدث)."""
    try:
        if df is None or not len(df) or not event_date:
            return None
        d = _norm_ts(event_date)
        rows = sorted(((_norm_ts(ts), i) for i, ts in enumerate(df.index)),
                      key=lambda x: x[0])
        hit = next((i for ts, i in rows if ts >= d), None)
        if hit is None:
            return None
        cl = float(df["Close"].iloc[hit])
        op = float(df["Open"].iloc[hit])
        prev = float(df["Close"].iloc[hit - 1]) if hit > 0 else op
        ref = max(op, prev)
        kind = "افتتاحه وإغلاق ما قبله"
        if not (ref == ref) or ref <= 0:        # NaN/تالف ⇒ لا حكم
            return None
        return {"accepted": bool(cl > ref), "close": round(cl, 2),
                "ref": round(ref, 2), "kind": kind,
                "date": str(df.index[hit])[:10]}
    except Exception:
        return None


def news_rejected_line(na) -> str:
    """⚠️ سطر «الخبر لم يُقبَل» — يظهر **فقط عند عدم القبول** (تحذير لا ضجيج)."""
    if not isinstance(na, dict) or na.get("accepted") is not False:
        return ""
    return (f"⚠️ إعلان {na.get('date', '')} لم يُقبَل: أغلق ${na['close']:g} تحت "
            f"{na['kind']} ${na['ref']:g} — فيصل: «خبره عدم قبوله = هبوط»")


def parse_yahoo_news(items, max_items: int, days: int) -> list:
    """يحوّل قائمة أخبار yfinance إلى عناوين نظيفة (آخر N يوم).
    يدعم البنيتين القديمة والجديدة لـ yfinance، ويرجع [] بلا أخطاء
    لو تغيّرت البنية أو لا توجد أخبار (Yahoo مصدر مجاني عبر yfinance)."""
    cutoff = dt.datetime.now(dt.timezone.utc) - dt.timedelta(days=days)
    out = []
    for it in (items or []):
        try:
            if not isinstance(it, dict):
                continue
            title = pub = link = None
            when = None
            # البنية الجديدة: كل الحقول داخل "content"
            if isinstance(it.get("content"), dict):
                c = it["content"]
                title = c.get("title")
                pub = (c.get("provider") or {}).get("displayName")
                cu = c.get("canonicalUrl") or c.get("clickThroughUrl") or {}
                link = cu.get("url") if isinstance(cu, dict) else None
                raw = c.get("pubDate") or c.get("displayTime")
                if raw:
                    try:
                        when = dt.datetime.fromisoformat(
                            str(raw).replace("Z", "+00:00"))
                    except Exception:
                        when = None
            # البنية القديمة: الحقول في الجذر مباشرة
            else:
                title = it.get("title")
                pub = it.get("publisher")
                link = it.get("link")
                ts = it.get("providerPublishTime")
                if ts:
                    try:
                        when = dt.datetime.fromtimestamp(
                            int(ts), dt.timezone.utc)
                    except Exception:
                        when = None
            if not title:
                continue
            if when is not None and when < cutoff:
                continue
            out.append({
                "title": str(title).strip(),
                "publisher": (pub or "").strip(),
                "link": (link or "").strip(),
                "date": when.date().isoformat() if when else "",
            })
            if len(out) >= max_items:
                break
        except Exception:
            continue
    return out


# ---- كشف أخبار الخطر تلقائياً (للبوت، لا يعتمد على المستخدم): يمسح عناوين
#      ياهو عن الطرح/التخفيف/التقسيم العكسي/الشطب → تحذير صريح في البطاقة.
#      الأنماط من الأخص للأعم (نأخذ أول تطابق لكل عنوان لتفادي التكرار). ----
NEWS_RISK_PATTERNS = [
    ("registered direct",    "طرح مباشر مسجّل (تخفيف)"),
    ("private placement",    "اكتتاب خاص (تخفيف)"),
    ("at-the-market",        "طرح ATM (تخفيف)"),
    ("at the market",        "طرح ATM (تخفيف)"),
    ("shelf offering",       "طرح رفّي (تخفيف)"),
    ("public offering",      "طرح عام (تخفيف)"),
    ("underwritten",         "طرح مكتتب (تخفيف)"),
    ("proposed offering",    "طرح مقترح (تخفيف)"),
    ("common stock offering", "طرح أسهم (تخفيف)"),
    ("convertible note",     "سند قابل للتحويل (تخفيف)"),
    ("convertible debenture", "سند قابل للتحويل (تخفيف)"),
    ("offering",             "طرح/تخفيف"),
    ("dilut",                "تخفيف (dilution)"),
    ("reverse stock split",  "تقسيم عكسي"),
    ("reverse split",        "تقسيم عكسي"),
    ("going concern",        "شك في الاستمرارية"),
    ("chapter 11",           "إفلاس (Chapter 11)"),
    ("bankrupt",             "إفلاس"),
    ("delist",               "خطر الشطب"),
]


def scan_news_risk(news) -> list:
    """يمسح عناوين الأخبار (Yahoo) عن إشارات الطرح/التخفيف/الخطر ويرجع
    تحذيراً عربياً واحداً مجمّعاً (أو [] لو لا خطر). يخدم البوت تلقائياً
    حتى قبل أن يصل الملف الرسمي لمرصد SEC."""
    labels = []
    for it in (news or []):
        low = (it.get("title") or "").lower()
        if not low:
            continue
        hit = None
        for kw, lbl in NEWS_RISK_PATTERNS:
            if kw in low:
                hit = lbl
                break
        # نمط "files to sell N units/shares" (مثل خبر EHGO) بلا كلمة offering
        if hit is None and "to sell" in low and (
                "unit" in low or "share" in low):
            hit = "طرح/تخفيف"
        if hit and hit not in labels:
            labels.append(hit)
    if labels:
        return [f"📰 خبر محتمل بالتخفيف/الخطر (Yahoo): "
                f"{' · '.join(labels)} — تحقّق"]
    return []


def _fetch_info(t):
    """جلب معلومات الشركة من Yahoo مع إعادة محاولة (info يُخنق كثيرًا)."""
    attempts = CONFIG.get("DOWNLOAD_RETRIES", 3)
    base = CONFIG.get("RETRY_BACKOFF", 3.0)
    last = {}
    for i in range(attempts):
        try:
            info = t.info or {}
            # نعتبرها ناجحة لو رجّعت حقولًا مفيدة (وإلا غالبًا خُنقت)
            if info.get("sector") or info.get("country") or \
                    info.get("floatShares") or info.get("longBusinessSummary"):
                return info
            if info and not last:
                last = info        # رد جزئي — نحتفظ به ونعيد المحاولة
        except Exception:
            pass
        if i < attempts - 1:
            time.sleep(base * (2 ** i))
    return last                    # أفضل رد جزئي توفّر بدل {} (كان يرمي الجزئي فتختفي البيانات)


def enrich(results: list) -> None:
    """إثراء المرشحين: شورت (Fintel→FINRA→Yahoo) + SEC + تقسيمات + أخبار"""
    syms = {r["symbol"] for r in results}
    # 🔬 التجميع الصامت أُزيل من الإثراء (2026-07-09): تجربة T-ACC فشلت بالسنتين
    # (غير مميِّز للمنفجر) فتقاعد عرضه من الكرت/اليومي/فحص اليد — لا نستهلك نداءات
    # Polygon لإشارة غير مُجدية. الدوال النقيّة + acc_verify.py محفوظة لإعادة الاختبار.
    _bor_budget = [0]        # 🔒 سقف طلبات احتياط الاقتراض/الفلوت من CE+iBorrow (فاشل-آمن)
    _ce_fails = [0]          # قاطع دائرة اقتراض ChartExchange: يتوقف بعد 3 إخفاقات
    _bor_fails = [0]         # قاطع دائرة iBorrowDesk: يتوقف بعد 3 إخفاقات متتالية
    _flt_fails = [0]         # 🏢 قاطع دائرة فلوت ChartExchange: يتوقف بعد 3 إخفاقات
    # 📄🆕 عدّادات SEC للتشغيلة الواحدة (تُصفَّر هنا كنمط `_bor_budget` — التدقيق لقّى
    # أنها كانت تراكمية تعيش عبر التشغيلات فتُطفئ الميزة صامتةً بعد 3 إخفاقات قديمة).
    _F4_FAILS[0] = 0
    _OFF_FAILS[0] = 0
    _F4_BUDGET[0] = int(CONFIG["FORM4_BUDGET"])
    fintel = {}
    try:
        fintel = fintel_short(sorted(syms))
    except Exception as e:
        log(f"⚠️ fintel: {e}")
    shorts = {}
    try:
        shorts = finra_daily_short(syms)
    except Exception as e:
        log(f"⚠️ FINRA: {e}")
    sec_cik_map()  # تحميل الخريطة مرة واحدة
    for r in results:
        r["fintel"] = fintel.get(r["symbol"]) or {}
        r["finra_short"] = shorts.get(r["symbol"])
        # سلسلة fintel→FINRA الموثّقة للقيمة المخزّنة (Yahoo يُضاف داخل كتلة .info)
        if r["finra_short"] is None:
            r["finra_short"] = r["fintel"].get("short_volume")
        # 🔒 معدّل الاقتراض (طلب المستخدم — فيصل: أساس الارتكاز):
        # ⚖️ **ChartExchange = المرجع الأول صراحةً** (قرار المستخدم 2026-07-10 «نعتمد
        # الموقع مرجعنا الأول» — مصدر فيصل نفسه، IBKR مباشر كل 15د). السلسلة:
        # **ChartExchange ← Fintel (احتياط، من طلب الشورت بلا نداء) ← iBorrowDesk**.
        # نبدأ بـNone ونملؤها بالأولوية. سقف نداءات مشترك + قاطع دائرة مستقل لكل مصدر.
        r["borrow_fee"] = None
        r["shares_available"] = None
        if _bor_budget[0] < 25 and _ce_fails[0] < 3:      # 1) CE أولًا (المرجع الأول)
            _bor_budget[0] += 1
            try:
                _ce = ce_borrow_info(r["symbol"])
            except Exception:
                _ce = {}
            if _ce:
                _ce_fails[0] = 0                           # نجاح → صفّر القاطع
                r["borrow_fee"] = _ce.get("borrow_fee")
                r["shares_available"] = _ce.get("shares_available")
            else:
                _ce_fails[0] += 1                          # إخفاق متتالٍ → قاطع بعد 3
        if r["borrow_fee"] is None and r["shares_available"] is None:
            # 2) Fintel احتياطًا (مُلتقط مجّانًا من طلب الشورت أعلاه)
            r["borrow_fee"] = r["fintel"].get("borrow_fee")
            r["shares_available"] = r["fintel"].get("shares_available")
        if (r["borrow_fee"] is None and r["shares_available"] is None
                and _bor_budget[0] < 25 and _bor_fails[0] < 3):
            _bor_budget[0] += 1
            try:
                _ib = iborrow_info(r["symbol"])
            except Exception:
                _ib = {}
            if _ib:
                _bor_fails[0] = 0                          # نجاح → صفّر القاطع
                r["borrow_fee"] = _ib.get("borrow_fee")
                r["shares_available"] = _ib.get("shares_available")
            else:
                _bor_fails[0] += 1                         # إخفاق متتالٍ (قد تكون الخدمة منقطعة)
        # نلتقط قيمة بوابة الفلوت/الشورت المجلوبة في scan_market كاحتياط أخير قبل
        # التصفير وإعادة الجلب (لا تضيع لو خُنق .info — إصلاح فحص 2026-06-24).
        _prev_float = r.get("float")
        _prev_short_pct = r.get("short_pct")
        r["short_pct"] = None
        r["float"] = None
        r["recent_split"] = None
        r["news"] = []
        r["tf4h"] = "غير متوفر"
        # إعلانات SEC الرسمية (هوية مضمونة بالـCIK)
        r["sec_filings"], r["sec_status"] = sec_recent_filings(r["symbol"])
        # 📅 دعوة اجتماع مساهمين (قناة _SEC_PROXY من النداء أعلاه — حدث قادم)
        r["proxy_filing"] = _SEC_PROXY.pop(r["symbol"].upper(), None)
        # 🆕 الطرح الجديد (حدث مؤسِّس عند فيصل) — من نفس النداء، صفر تكلفة
        r["offering_event"] = _SEC_FOUNDING.pop(r["symbol"].upper(), None)
        _SEC_OFFERING.pop(r["symbol"].upper(), None)   # تنظيف القناة الواسعة
        # 📄 شراء الداخليين (Form 4): الميتا مجانية أعلاه · المستند بسقف صارم هنا
        # (بعد select_top ⇒ ≤ سعة القائمة). فاشل-آمن: [] عند أي تعذّر.
        r["insider_buys"] = form4_insider_buys(
            r["symbol"], cap=int(CONFIG["FORM4_MAX_FETCH"]))
        time.sleep(0.15)  # احترام حد SEC (10 طلبات/ثانية)
        if yf is None:
            continue
        try:
            t = yf.Ticker(r["symbol"])
            try:
                info = _fetch_info(t)                 # مع إعادة محاولة
                sym = r["symbol"]
                cached = COMPANY_CACHE.get(sym, {})    # آخر قيم معروفة
                sp = info.get("shortPercentOfFloat")
                # 🔑 خطة 019-ب: `if sp` كان يعدّ **الصفرَ غيابًا** فيستبدله بقيمةٍ
                # قديمة — و«صفر شورت» عند فيصل **قراءةٌ إيجابية** لا نقصُ بيانات
                # (نظيرُ قاعدة «تعذّر ≠ صفر» مقلوبةً). الآن: الصفرُ يُعرَض صفرًا،
                # و`None` وحدَه يرتدّ للذاكرة.
                r["short_pct"] = (round(sp * 100, 1) if sp is not None
                                  else cached.get("short_pct") or _prev_short_pct)
                # عدد الشورت (حجم يومي): لو غاب عن FINRA/Fintel استرجع آخر قيمة
                # معروفة من الذاكرة — نفس المقياس بالضبط (لا نخلط بفائدة شورت
                # Yahoo «sharesShort» بالملايين؛ بديل Yahoo يُعرَض كنسبة من الفلوت
                # عبر short_pct). تغطية ثابتة بلا تلوّث مقياس.
                if r.get("finra_short") is None:
                    r["finra_short"] = cached.get("finra_short")
                # 📊 الشورت الرسمي (SI) + أيام التغطية (🎬 فيصل قرأهما بفيديو DSY من
                # Fintel: 37,993 · 0.30). حقلان مستقلان بمقياسهما — **لا يُخلطان
                # بfinra_short** (الحجم اليومي). عرض/سياق فقط — خارج M13/الفرز.
                r["short_interest"] = _or_cache(info.get("sharesShort"),
                                                cached, "short_interest")
                r["days_to_cover"] = _or_cache(info.get("shortRatio"),
                                               cached, "days_to_cover")
                # القيمة المجلوبة إن وُجدت، وإلا آخر قيمة معروفة (لا يختفي 🏢)
                r["float"] = (_or_cache(info.get("floatShares"), cached, "float")
                              or _prev_float)
                # 🏢 آخر ملاذ للفلوت لو غاب من ياهو (`_fetch_info` مخنوق) والذاكرة.
                # بودجت + قاطع دائرة مستقل، فاشل-آمن.
                # 🔴 **إصلاح 2026-07-28 (`plans/003`):** كان `ce_float_info` وهي ميتة
                # منذ 07-24 ⇒ يحرق الميزانية والقاطع بلا أي فائدة. البديل = ياهو
                # بمحاولة طازجة (`_fetch_info` أعلاه استنفد محاولاته الثلاث).
                # ⚠️ `strict=True`: `refloat_gate_recheck` تقرأ `r["float"]` **بعد**
                # هذي الكتلة مباشرةً في مسارَي الاختيار (التجديد + الإضافة اليومية)،
                # فسقوطٌ لـ`sharesOutstanding` هنا = بوّابة M14 أشدّ صامتةً.
                if (r["float"] is None
                        and _bor_budget[0] < 25 and _flt_fails[0] < 3):
                    _bor_budget[0] += 1
                    try:
                        _cf = _yahoo_float(sym, strict=True)
                    except Exception:
                        _cf = None
                    if _cf:
                        _flt_fails[0] = 0
                        r["float"] = _cf
                    else:
                        _flt_fails[0] += 1
                # D10: تدوير الفلوت (حجم اليوم ÷ الفلوت) — إشارة سكويز عند تجاوز
                # 100% (فيصل ELAB: تدوير 750%). عرض فقط — لا نقاط ولا بوابة.
                _flt, _vt = r.get("float"), r.get("vol_today")
                if _flt and _vt:
                    r["rotation_pct"] = round(_vt / _flt * 100.0)
                r["sector"] = _or_cache(info.get("sector") or
                                        info.get("industry"), cached, "sector")
                r["industry"] = _or_cache(info.get("industry"),
                                          cached, "industry")
                # 📅 اسم الشركة (لمطابقة راعي التجارب السريرية — الأحداث المعلنة)
                # ⑦ (إصلاح تدقيق 2026-07-12): تعقيم عند الحد — نص حرّ من مصدر
                # خارجي يُكوَّت في weekly_watchlist.json الذي يقرأه وكيل Cline
                # (contents: write). محارف محافظة + سقف طول، فلا يحمل الحقلُ
                # تعليماتٍ لنموذج لغوي ولا وسومًا.
                r["company_name"] = _sanitize_name(info.get("shortName")
                                                   or info.get("longName")
                                                   or cached.get("company_name"))
                # 📅 تاريخ أول تداول (لتقدير انتهاء حظر المؤسسين للإدراجات الحديثة)
                try:
                    _ftd = info.get("firstTradeDateEpochUtc")
                    if _ftd:
                        r["first_trade"] = dt.datetime.fromtimestamp(
                            int(_ftd), dt.timezone.utc).date().isoformat()
                except Exception:
                    pass
                if not r.get("first_trade"):
                    r["first_trade"] = cached.get("first_trade")
                summ = info.get("longBusinessSummary") or ""
                r["business"] = ((summ[:160].strip() + "…") if summ
                                 else cached.get("business"))
                r["country"] = _or_cache(info.get("country"), cached, "country")
                r["cash"] = _or_cache(info.get("totalCash"), cached, "cash")
                r["revenue"] = _or_cache(info.get("totalRevenue"),
                                         cached, "revenue")
                r["shares_out"] = _or_cache(info.get("sharesOutstanding"),
                                            cached, "shares_out")
                # §12 session_context (نسخة دنيا صادقة): snapshot جلسة اليوم من
                # المتاح فعلًا فقط — ما قبل/بعد السوق غير متاح بمسار البوت →
                # سبب صريح بدل التخمين (خطة طبقة التفسير). عرض/تخزين فقط.
                r["session_ctx"] = {
                    "open": info.get("regularMarketOpen") or info.get("open"),
                    "high": (info.get("regularMarketDayHigh")
                             or info.get("dayHigh")),
                    "low": (info.get("regularMarketDayLow")
                            or info.get("dayLow")),
                    "prev_close": (info.get("regularMarketPreviousClose")
                                   or info.get("previousClose")),
                    "volume": (info.get("regularMarketVolume")
                               or info.get("volume")),
                    "market_cap": info.get("marketCap"),
                    "pre_after": None,
                    "unavailable_reason": ("بيانات ما قبل/بعد السوق غير متاحة "
                                           "بمسار البوت — لا تخمين"),
                }
                # N3 (لوحة علامات اليد): لقطة الطلبات الصادقة — bid/ask وحيدة وقت
                # الفرز. تدفق الطلبات الحي (Level 2) غير متاح بمسارنا → يُقال صراحة،
                # لا يُخمَّن. السبريد الواسع = علامة ضعف سيولة/يد تتحكّم بالعرض.
                _bid, _ask = info.get("bid"), info.get("ask")
                _spread = None
                if _bid and _ask and _ask > 0 and _ask >= _bid:
                    _spread = round((_ask - _bid) / _ask * 100.0, 1)
                r["session_ctx"]["quote"] = {
                    "bid": _bid, "ask": _ask,
                    "bid_size": info.get("bidSize"),
                    "ask_size": info.get("askSize"), "spread_pct": _spread,
                    "note": ("لقطة وحيدة وقت الفرز — تدفق الطلبات الحي غير متاح "
                             "بمسار البوت"),
                }
                # 🌙 إكمال pre_after بصدق (POLYGON_EDGE_PLAN §ج): **لو** المفتاح موجود
                # وداخل نافذة البريماركت، املأ ببيانات Polygon الفعلية وبدّل السبب —
                # وإلا يبقى None بسببه الصريح (لا تخمين). فاشل-آمن (يكمل P1-1 بشرف).
                if os.environ.get("POLYGON_API_KEY", "").strip():
                    try:
                        _pm = polygon_premarket(
                            r["symbol"], prev_close=r["session_ctx"].get("prev_close"))
                        if _pm:
                            r["session_ctx"]["pre_after"] = _pm
                            r["session_ctx"]["unavailable_reason"] = \
                                "من Polygon (اشتراك المستخدم)"
                    except Exception:
                        pass
                # حدّث الذاكرة بالقيم المعروفة الآن (للتشغيلات القادمة)
                _cc_entry = {k: r.get(k) for k in
                             ("sector", "industry", "business",
                              "country", "cash", "revenue",
                              "shares_out", "short_pct", "float",
                              "finra_short", "company_name", "first_trade",
                              "short_interest", "days_to_cover")
                             if r.get(k) is not None}
                COMPANY_CACHE.pop(sym, None)      # LRU: ينقله لأحدث موضع
                COMPANY_CACHE[sym] = _cc_entry
                # تحذير جغرافي (تحذير فقط — السهم يظل يظهر حتى في A)
                if r.get("country") in CONFIG.get("HIGH_RISK_COUNTRIES", []):
                    r.setdefault("warnings", []).append(
                        f"بلد عالي التلاعب ({ar_country(r['country'])}) — "
                        "غالباً يتجاهل التحليل الفني؛ تحقق يدوياً")
            except Exception:
                pass
            try:
                cutoff = pd.Timestamp.today(tz="UTC") - pd.Timedelta(
                    days=CONFIG["SPLIT_LOOKBACK_DAYS"])
                sp = t.splits
                if sp is not None and len(sp):
                    idx = sp.index.tz_localize("UTC") if sp.index.tz is None \
                        else sp.index.tz_convert("UTC")
                    recent = sp[idx >= cutoff]
                    rev = recent[recent < 1.0]
                    if len(rev):
                        r["recent_split"] = (str(rev.index[-1].date()),
                                             float(rev.iloc[-1]))
            except Exception:
                pass
            # أخبار ياهو (مجانية عبر yfinance) — عناوين آخر N يوم
            try:
                r["news"] = parse_yahoo_news(
                    t.news, CONFIG["NEWS_MAX_SHOW"], CONFIG["NEWS_DAYS"])
            except Exception:
                r["news"] = []
            # فحص آلي لعناوين الأخبار عن الطرح/التخفيف/الخطر → تحذير بالبطاقة
            for _w in scan_news_risk(r["news"]):
                r.setdefault("warnings", []).append(_w)
            # فريم 4 ساعات: تأكيد الانعكاس + مستويات فيصل (دعوم/أهداف/انقلاب)
            try:
                h4, _h1 = fetch_4h(r["symbol"], with_h1=True)
                # 🌙 «اليوميُّ فوّت هذا» — من **نفس** الشموع الساعيّة المجلوبة
                #    هنا (‏`prepost=True`) ⇒ صفرُ نداءٍ شبكيٍّ إضافيّ. عرضٌ فقط.
                try:
                    r["ah_missed"] = ah_missed_extremes(_h1)
                except Exception:                                # noqa: BLE001
                    r["ah_missed"] = None
                if h4 is not None:
                    _ok4 = timeframe_reversal(h4, 60, 20)
                    r["tf4h"] = "✅ مؤكِّد" if _ok4 else "⏳ غير مؤكِّد بعد"
                    r["h4_levels"] = four_hour_levels(h4, r["price"])
                    # دمج فيصل (#1+#3): أهداف 4س في t2/t3 (t1/RR مقفولان) +
                    # تأكيد 4س للترتيب — بنفس بيانات الـ4س المجلوبة (بلا تحميل زائد).
                    r["t2"], r["t3"] = refine_targets_4h(
                        r["t1"], r["t2"], r["t3"], r["price"], r["h4_levels"])
                    # حدّث rr2 بعد تنقيح t2 (يُكتب في CSV الأسبوعي) — من متوسط
                    # الدفعات نفسه، فلا يتعارض مع t2 الجديد (t1/rr مقفولان).
                    # 🎯 صدقُ RR — أ-1-ب (2026-08-13): فوق نطاق الدفعات يُقاس
                    #    من السعر الحالي **كما في `analyze_ticker`** وإلّا حمل
                    #    الصفُّ الواحد مقياسين (`rr` صادقٌ و`rr2` مخطَّط) —
                    #    وهو يُصدَّر في CSV المشرف. داخل النطاق ⇒ بت-بت.
                    try:
                        _er = sum(r["tranches"]) / len(r["tranches"])
                        _bt = max(r["tranches"]) * (1 + CONFIG.get(
                            "ENTRY_READY_BAND_TOL_PCT", 0.0) / 100.0)
                        _ref2 = (r["price"] if r["price"] > _bt else _er)
                        r["rr2"] = (r["t2"] - _ref2) / max(
                            _ref2 - r["stop"][0], 1e-9)
                    except Exception:
                        pass
                    r["h4_confirm"] = h4_confirm_score(r)
                    # 🎬 KST على 4س بإعدادات فيصل (فيديو DSY) — حالة زخم مساندة.
                    # عرض/سياق فقط — لا نقاط ولا بوابة (المؤشر مساند لا أساس).
                    try:
                        r["kst4"] = momentum_kst_state(h4["Close"])
                    except Exception:
                        r["kst4"] = None
                else:
                    r["tf4h"] = "غير متوفر"
            except Exception:
                r["tf4h"] = "غير متوفر"
        except Exception:
            continue
        # 📅 الأحداث المعلنة القادمة (أرباح + تجارب سريرية للرعاية الصحية) —
        # فاشل-آمن → None (عرض/سياق فقط، «يوم الانفجار الذي ينتظره المضارب»)
        try:
            r["upcoming_events"] = upcoming_events(
                r["symbol"], r.get("company_name"), r.get("sector"),
                r.get("proxy_filing"), r.get("first_trade"))
        except Exception:
            r["upcoming_events"] = None
        time.sleep(0.5)
    _save_company_cache(COMPANY_CACHE)   # حفظ آخر القطاعات/الدول المعروفة
    # 🧭 تجديد طبقة التفسير **بعد** الإثراء (إصلاح 2026-07-07): h4_levels والأخبار
    # وSEC والتقسيم وتنقيح t2/t3 كلها تُضاف هنا — التفسير المحسوب قبلها كان يفوته
    # سياق 4س وأعلام الخطر. عرض/تفسير فقط؛ حارس «لا يمسح الموجود»: لو رجع فارغًا
    # (سجل بلا سعر/قاع) يبقى التفسير المخزّن كما هو.
    for r in results:
        try:
            _ip = build_interpretation(r)
            if _ip:
                r["interp"] = _ip
        except Exception:
            pass


# ==========================================================
# 7) استراتيجية التقسيم العكسي
# ==========================================================
def _split_frequency(splits, today, days: int = 365) -> int:
    """🔁 عدد التقسيمات العكسية (نسبة أقل من 1) في آخر `days` يومًا (سنة افتراضيًا).
    قاعدة فيصل (FAISAL_OPERATOR_PACK §P4، من الصور): «اذا تقسيم كثير خلال فتره زمنيه
    قصيره غالبا مايطول، سبوع بالكثير» (مثل ZCMD حقّق 600% ثم ارتدّ). دالة نقيّة ·
    فاشلة-آمنة (بيانات مفقودة/غير صالحة → 0). تقبل pandas Series (فهرسها تواريخ ·
    قيمتها نسبة التقسيم) أو قائمة أزواج (تاريخ, نسبة). `today` = dt.date. **عرض/تحذير
    فقط — خارج الفرز نهائيًا** (لا يمسّ الدخول/الوقف/الأهداف/العضوية).

    🔴 **إصلاحُ نظرٍ مستقبليّ (2026-08-13، أمرُ المالك «صلّح كل شي متأكد منه» — كان
    مُبلَّغًا بلا إصلاح):** الشرطُ كان `d >= cutoff` **بلا حدٍّ أعلى** ⇒ يَعُدّ تقسيمًا
    يقع **بعد** يوم المرجع. حيًّا لا أثرَ له (‏`today` هو اليوم فلا تقسيمَ مستقبليّ)
    **لكن أدوات المشي التاريخيّ تمرّر `today` قديمًا** فكان الحقلُ يقرأ المستقبل.
    الآن **نافذةٌ مغلقة الطرفين** `cutoff <= d <= today`. ⚠️ **يُشدّد لا يُرخي.**"""
    try:
        cutoff = today - dt.timedelta(days=days)
        if hasattr(splits, "index") and hasattr(splits, "values"):
            pairs = list(zip(splits.index, splits.values))
        else:
            pairs = list(splits or [])
        n = 0
        for ts, ratio in pairs:
            try:
                d = ts.date() if hasattr(ts, "date") else ts
                if isinstance(d, str):
                    d = dt.date.fromisoformat(d[:10])
                if float(ratio) < 1.0 and cutoff <= d <= today:
                    n += 1
            except Exception:
                continue
        return n
    except Exception:
        return 0


def _split_freq_line(freq) -> str:
    """سطر تحذير «تقسيمات متكررة = نَفَس قصير» (عند تقسيمين فأكثر في سنة). عرض فقط —
    يرجع "" لو أقل من تقسيمين (لا حشو). موحَّد بين قسم D9 وفحص اليد."""
    if (freq or 0) >= 2:
        return (f"🔁 تقسيمات متكررة ({int(freq)} في سنة) — قاعدة فيصل: الصعود "
                "غالبًا لا يتجاوز أسبوعًا (ZCMD صعد 600% ثم ارتدّ)")
    return ""


def short_targets_report(post_split_high=None, price=None, avail=None,
                         float_shares=None, pump=None, offering=None,
                         next_bottom=None, sweep=None, rose_pct=None):
    """🎯 **«تحديد أهداف الشورت»** — منظومة فيصل كاملةً في مُخرَج واحد (TG_1813 + TG_2041).

    نصّه (TG_1813): «تحديد أهداف الشورت · برنامج اشتراكه ألف دولار شهري ما يصلح إلا
    للمحللين · **انت عليك فقط تابع الشورت — إذا صفر أو قريب من الصفر يكون إيجابي
    السهم** · الشروط: ① سهم مقسم هابط متوسط 20<30<50 شرط ما صعد أول ما قسم أكثر من
    20% ② خلال متوسط الحركة 20 يتضح لك وجهة السهم · هل عليه قروبات · **هل ضرب قيعان
    جديدة وهذا الأصل** · كم القاع؟ **غالبًا يهبط النص** · فتح 5 يهبط بين 2 ← 2.50 ·
    **يكون تحت عينك هدفه شمعة الهبوط 5 = 100%** ③ سهم عليه قروبات **هجّ عنه** ④ سهم
    شورته حلو وهابط بعد صعود عالٍ خلال متوسط 10<20 = **ردة فعل** مع جني ربح ⑤ ابحث عن
    **عدد أسهم الشركة + أخبارها · ما يكون عليه طرح**».

    وعدديًّا (TG_2041): «6 كان دعم ارتفع هبوط لقاع 4.21 · **إذا الهبوط الأول 30% من
    القاع نحسب قاع جديد من 4.21** · 4.21−30%=2.94» ⇒ `next_bottom`.

    كل الوسائط اختيارية ⇒ ما تعذّر **يُصرَّح به** ولا يُخمَّن. يرجّع قائمة أسطر (أو []).
    نقيّة · فاشلة-آمنة · **عرض/سياق فقط — خارج الفرز والدخول والوقف والأهداف.**"""
    try:
        L = ["🎯 <b>أهداف الشورت</b> (منظومة فيصل — أين يتّجه هبوطًا وأين تنتظره)"]
        half = (float(post_split_high) / 2.0
                if post_split_high and float(post_split_high) > 0 else None)
        if half:
            L.append(f"  ⬇️ الهدف الأول = القمة ÷2 = <b>${half:.2f}</b>"
                     + (f" (القمة ${float(post_split_high):.2f})"))
            if price and float(price) > 0:
                _d = (float(price) / half - 1.0) * 100.0
                L.append("  📍 السعر الآن " + (f"فوقه بـ{_d:.0f}%" if _d >= 0
                                              else f"تحته بـ{abs(_d):.0f}%"))
        else:
            L.append("  ⬇️ الهدف الأول (القمة ÷2): — (لا قمة ما بعد حدث مؤسِّس)")
            # 🚧 **حاجز خلط صريح** (تدقيق 2026-07-27): منظومة «أهداف الشورت» مبنيّة على
            # **سهم مقسّم/مطروح هابط** (شرط فيصل ①). بلا حدث مؤسِّس لا ينطبق الـ÷2،
            # فيُقال ذلك في المُخرَج نفسه بدل ترك القارئ يظنّ أن الباقي حكمٌ بهبوطه.
            L.append("  ℹ️ لا تقسيم/طرح مؤسِّس ⇒ <b>منظومة الـ÷2 لا تنطبق هنا</b>؛ "
                     "الأسطر أدناه سياق عامّ (شورت/قروبات) لا حكم هبوط.")
        if next_bottom and next_bottom.get("next_bottom"):
            L.append(f"  ⬇️ لو كسر القاع: <b>${next_bottom['next_bottom']:.2f}</b> "
                     f"(بنسبة هبوطه الأولى {next_bottom['drop_pct']:.0f}%)")
        if sweep:
            L.append(f"  🩸 سحب السيولة المتوقَّع: <b>${float(sweep):.2f}</b>")
        # ⑤ «انت عليك فقط تابع الشورت — صفر أو قريب من الصفر = إيجابي»
        if avail is None:
            L.append("  🕵️ الشورت المتاح: — (تعذّر · وهو **الرقم الذي يقول فيصل إنه "
                     "كل ما تحتاجه**)")
        else:
            a = float(avail)
            tag = ("✅ <b>صفر أو قريب منه = إيجابي</b> (نصّ فيصل)" if a <= 1000
                   else "✅ ممتاز (تحت 10 آلاف)" if a <= 10000
                   else "🟢 جيّد (تحت 20 ألفًا)" if a <= 20000
                   else "🟡 مرتفع" if a <= 50000
                   else "⛔ <b>ذخيرة هبوط</b> (حرب وتصريف)")
            L.append(f"  🕵️ الشورت المتاح: <b>{fmt_money(a)}</b> — {tag}")
        if float_shares:
            # ⚠️ شرط فيصل ⑤ نصّه «عدد أسهم الشركة»، والمتاح عندنا هو **الفلوت**
            # (المتداوَل حرًّا) وهو أقلّ من الأسهم القائمة — يُسمّى باسمه لا باسم فيصل.
            L.append(f"  🏢 الفلوت (المتداوَل حرًّا): {fmt_money(float(float_shares))}"
                     " — الأسهم القائمة غير متاحة عندنا")
        if pump is not None:
            L.append("  ⛔ <b>عليه قروبات — «هجّ عنه»</b> (نصّ فيصل)" if pump
                     else "  ✅ خالٍ من رفعات القروبات")
        if offering is not None:
            L.append("  ⛔ <b>عليه طرح</b> (فيصل: «ما يكون عليه طرح»)" if offering
                     else "  ✅ لا طرح جديد مرصود")
        if rose_pct is not None:
            L.append(f"  {'✅' if float(rose_pct) <= CONFIG['SPLIT_ROSE_MAX_PCT'] else '⛔'}"
                     f" صعوده بعد الحدث {float(rose_pct):.0f}% "
                     f"(شرط فيصل: لا يتجاوز {CONFIG['SPLIT_ROSE_MAX_PCT']:.0f}%)")
        # ⚠️ السطر الختامي يصف **هدف وصفة الـ÷2**؛ فطبعه بعد إعلان «لا تنطبق هنا»
        # تناقضٌ صريح (تدقيق 2026-07-27) ⇒ يُقصَر على وجود الحدث المؤسِّس.
        if half:
            L.append("  ℹ️ فيصل: «<b>انت عليك فقط تابع الشورت</b>» — الهدف الصاعد "
                     "بعدها = الشمعة الساقطة الأولى (+100%)")
        else:
            L.append("  ℹ️ فيصل: «<b>انت عليك فقط تابع الشورت</b>»")
        return L
    except Exception:                                    # noqa: BLE001
        return []


def _split_row(sym, split_date, day_open, price, short, freq=None):
    """صفّ تقرير التقسيم العكسي (D9): هدف الهبوط = افتتاح التقسيم ÷ 2 (فيصل
    EHGO 2.80÷2=1.40)؛ والشورت «مقبول» لو أقل من SHORT_DAILY_MAX («تابعه لين
    الشورت تحت 20 ألف»). `freq` = عدد التقسيمات العكسية في آخر سنة (قرينة فيصل §P4،
    عرض فقط). دالة نقية قابلة للاختبار بلا شبكة."""
    target = round(day_open / 2.0, 2) if day_open else None
    ok = (short is not None and short < CONFIG["SHORT_DAILY_MAX"])
    return {"symbol": sym, "split_date": str(split_date), "open": day_open,
            "half": target, "price": price, "short": short, "short_ok": ok,
            "freq": freq}


def split_watch_report(history: dict) -> list:
    """مراقبة قائمة التقسيمات اليدوية: قاع متوقع = شمعة التقسيم ÷ 2"""
    rows = []
    if yf is None:
        return rows
    watch = [s for s in CONFIG["SPLIT_WATCHLIST"] if s in history]
    if not watch:
        return rows
    shorts = {}
    try:
        shorts = finra_daily_short(set(watch))
    except Exception:
        pass
    for sym in watch:
        try:
            t = yf.Ticker(sym)
            sp = t.splits
            if sp is None or not len(sp):
                continue
            idx = sp.index.tz_localize("UTC") if sp.index.tz is None \
                else sp.index.tz_convert("UTC")
            cutoff = pd.Timestamp.today(tz="UTC") - pd.Timedelta(
                days=CONFIG["SPLIT_LOOKBACK_DAYS"])
            recent = sp[idx >= cutoff]
            rev = recent[recent < 1.0]
            if not len(rev):
                continue
            split_date = rev.index[-1].date()
            df = history[sym]
            day_open = None
            try:
                after = df[df.index.tz_localize(None) >= pd.Timestamp(split_date)] \
                    if df.index.tz is not None else \
                    df[df.index >= pd.Timestamp(split_date)]
                if len(after):
                    day_open = float(after["Open"].iloc[0])
            except Exception:
                pass
            price = float(df["Close"].iloc[-1])
            freq = _split_frequency(sp, dt.date.today())   # §P4 (نفس بيانات sp)
            rows.append(_split_row(sym, split_date, day_open, price,
                                   shorts.get(sym), freq))
        except Exception:
            continue
    return rows


def build_split_watch_section(rows: list) -> str:
    """قسم «مراقبة التقسيم العكسي» (D9): يفعّل قاعدة فيصل ÷2 النائمة — عرض فقط."""
    if not rows:
        return ""
    lines = ["✂️ <b>مراقبة التقسيم العكسي</b> (هدف الهبوط = افتتاح التقسيم ÷2):"]
    for r in rows:
        half = f"${r['half']:.2f}" if r.get("half") else "—"
        if r.get("short") is not None:
            stag = (f"شورت {fmt_money(r['short'])} "
                    + ("✓" if r.get("short_ok") else "⚠️ عالٍ"))
        else:
            stag = "شورت —"
        lines.append(f"• <b>{esc(r['symbol'])}</b> ${r['price']:.2f} · "
                     f"هدف هبوط {half} · {stag}")
        _fl = _split_freq_line(r.get("freq"))              # §P4 (عرض/تحذير فقط)
        if _fl:
            lines.append("  " + _fl)
    lines.append("<i>القاع المتوقع بعد التقسيم ≈ نصف افتتاح التقسيم (فيصل).</i>")
    return _rtl_join(lines)


def _offering_event(sym, today=None, fetch=None, lookback=None):
    """🆕 **الطرح الجديد كحدث مؤسِّس** (بطاقة فيصل MWC: «طرح جديد تاريخ 14/5 · افتتاح
    8.10 · أعلى 26.38» — نفس بنية بطاقة «قسم» حرفيًّا). يبحث عن أحدث نموذج طرح/تسجيل
    (`_OFFERING_FORMS`) خلال نافذة `SPLIT_LOOKBACK_DAYS`.
    يقرأ أولًا القناة المجانية `_SEC_OFFERING` (لو مُلئت من `sec_recent_filings`)، وإلا
    يجلب ملخّص SEC مباشرةً بسقف نداءات وقاطع دائرة. `fetch(url)` محقون للاختبار.
    يرجّع {"date","form"} أو None. فاشل-آمن مطلق · **خارج الفرز** (أداة الصيّاد فقط)."""
    s = str(sym).upper()
    today = today or dt.date.today()
    lb = int(lookback or CONFIG["SPLIT_LOOKBACK_DAYS"])

    def _fresh(ev):
        """حدث مؤسِّس صالح = **نشرة نهائية** حديثة (لا تسجيل رفّي روتيني)."""
        try:
            if (ev.get("form") or "").strip() not in _FOUNDING_OFFERING_FORMS:
                return None
            d = dt.date.fromisoformat(str(ev["date"])[:10])
            return ev if (0 <= (today - d).days <= lb) else None
        except Exception:
            return None
    got = _SEC_FOUNDING.get(s)
    if got:
        return _fresh(got)
    if fetch is None and _OFF_FAILS[0] >= 3:       # قاطع دائرة مستقلّ للطرح
        return None
    try:
        cik = sec_cik_map().get(s)
        if not cik:
            return None
        url = f"https://data.sec.gov/submissions/CIK{cik:010d}.json"
        if fetch is not None:
            data = fetch(url)
        else:
            rr = requests.get(url, headers=SEC_UA, timeout=30)
            if rr.status_code != 200:
                _OFF_FAILS[0] += 1
                return None
            data = rr.json()
            time.sleep(0.15)
        recent = ((data.get("filings") or {}).get("recent")) or {}
        forms = recent.get("form", []) or []
        dates = recent.get("filingDate", []) or []
        for i, f in enumerate(forms):
            # **امسح كل القائمة** ولا ترجع عند أول تطابق واسع: النماذج مرتّبة من
            # الأحدث، وأحدثُ تسجيل رفّي روتيني كان يحجب النشرة النهائية الأقدم.
            if (f or "").strip() in _FOUNDING_OFFERING_FORMS:
                ev = _fresh({"form": (f or "").strip(),
                             "date": dates[i] if i < len(dates) else ""})
                if ev:
                    return ev
        return None
    except Exception:
        _OFF_FAILS[0] += 1
        return None


def _split_setup_probe(df, splits, today, tol: float = 0.25, offering=None):
    """🎯 مِجَسّ setup أسهم التقسيم (فيصل IMG_0143/0144/0150/0151 — عرض/سياق فقط).
    يكتشف من OHLCV+splits نمطَ «مقسّم عكسيًّا · وصل قاع القمة÷2 · حافظ عليه» ويرجع
    dict وصفيًّا أو None. **مرجع فيصل الحرفي**: القاع المتوقّع = **قمة ما بعد التقسيم** ÷2
    (`_post_split_high`؛ JEM 6.90÷2=3.45 · WORX 2.33÷2=1.16 — تحقّق حيّ على JEM أكّده) +
    معيار «لم يصعد بعد التقسيم» (`didnt_rise`، IMG_0150 «قسم ما أعطى صعود»).
    🆕 **2026-07-27 (بطاقة فيصل الفرزية):** (أ) الحدث المؤسِّس قد يكون **طرحًا جديدًا**
    لا تقسيمًا (MWC: «طرح جديد 14/5 · افتتاح 8.10 · أعلى 26.38» — نفس البنية حرفيًّا)
    فيُقبل عبر `offering` **فقط عند غياب تقسيم عكسي حديث** (`offering=None` ⇒ السلوك
    السابق بت-بت). (ب) قاعدة «لم يصعد» صارت من **افتتاح يوم الحدث** لا إغلاق أول شمعة
    (HTCR افتتاح 3.72 → أعلى 4.58 = +23% هادئ · BNKK 3.69 → 7.19 = +95% انضخّ)، مع
    ارتداد للإغلاق لو تعذّر الافتتاح. نقيّ · فاشل-آمن
    · بلا تسريب (يستعمل تقسيمات ≤ آخر شمعة). **خارج الفرز نهائيًا** (لا يمسّ الاختيار)."""
    try:
        if df is None or len(df) < 20 or splits is None:
            return None
        high, close = df["High"], df["Close"]
        cut = df.index[-1]
        # (1) تقسيم عكسي حديث (نسبة<1) داخل النافذة (بلا تسريب: التاريخ ≤ اليوم)
        # ⚠️ **`hasattr(x, "index")` صحيح للقوائم أيضًا** (`list.index` دالّة!) فالفحص
        # القديم كان يسقط على `.values` ⇒ **None صامتة لأي إدخال قائمة** خلافًا للتوثيق.
        # (الإنتاج يمرّر Series من `_fetch_splits` فسلوكه لم يتغيّر — لُقِّي ببناء اختبار.)
        pairs = (list(zip(splits.index, splits.values))
                 if hasattr(splits, "values") and hasattr(splits, "index")
                 else list(splits or []))
        rev = []
        for ts, ratio in pairs:
            try:
                d = ts.date() if hasattr(ts, "date") else ts
                if isinstance(d, str):
                    d = dt.date.fromisoformat(d[:10])
                if (float(ratio) < 1.0 and d <= today
                        and (today - d).days <= CONFIG["SPLIT_LOOKBACK_DAYS"]):
                    rev.append(d)
            except Exception:
                continue
        # 🆕 حدث مؤسِّس بديل: **طرح جديد** (بطاقة فيصل MWC) — يعامله تمامًا كـ«قسم»
        # (تاريخ · افتتاح · أعلى بعده). يُستعمل فقط عند غياب تقسيم عكسي حديث، فلا
        # يغيّر سلوك المقسّم إطلاقًا. `offering=None` ⇒ السلوك السابق حرفيًّا.
        ev_kind, ev_date = "split", (max(rev) if rev else None)
        if not rev:
            od = None
            try:
                od = (dt.date.fromisoformat(str(offering["date"])[:10])
                      if offering and offering.get("date") else None)
            except Exception:
                od = None
            if not (od and od <= today
                    and (today - od).days <= CONFIG["SPLIT_LOOKBACK_DAYS"]):
                return None
            ev_kind, ev_date = "offering", od
        # (2) قمة ما بعد الحدث ÷2 (مرجع فيصل الحرفي — JEM 6.90÷2=3.45 · WORX 2.33÷2=1.16).
        # تصحيح 2026-07-24: التحقّق على JEM أثبت أن `_post_split_high` (=6.90) يطابق فيصل،
        # وأن «إغلاق أول شمعة» (=6.05) ابتعد عنه — فأُرجع المرجع للقمة (كان صحيحًا أصلًا).
        ref = (_post_split_high(high, splits, cut) if ev_kind == "split"
               else _post_event_high(high, ev_date))
        if not ref or ref <= 0:
            return None
        half = round(ref / 2.0, 2)
        price = float(close.iloc[-1])
        if price <= 0:
            return None
        _lo, _hi = half * CONFIG["SPLIT_RADAR_BAND_LOW"], half * (1.0 + tol)
        # (3) وصل القاع: السعر **قرب** القمة÷2 — ضمن نطاق [÷2×BAND_LOW ، ÷2×(1+tol)].
        near_bottom = (_lo <= price <= _hi)
        # (4) حافظ على القاع ≥3 جلسات **عند مستوى الـ÷2** (فيصل «ضرب قاع الـ÷2 وحافظ عليه 3ج» —
        # مربوط بالمستوى لا «±12%» مبهمًا).
        tail = [float(x) for x in close.tail(3)]
        held_ok = (len(tail) >= 3 and all(_lo <= x <= _hi for x in tail))
        # (5) «لم يصعد بعد التقسيم» (فيصل IMG_0150: «قسم ما أعطى صعود» — الـsetup للمقسّم الهادئ):
        # لو ارتفع من قيمة شمعة التقسيم (أول إغلاق) للقمة بأكثر من SPLIT_ROSE_MAX_PCT = انضخّ (مو
        # هادئًا). فاشل-آمن (لا قيمة شمعة → لا حكم = didnt_rise=True احتياطًا).
        # ⚖️ تصحيح 2026-07-27 من **بطاقة فيصل الفرزية**: القاعدة = **افتتاح يوم الحدث**
        # لا إغلاق أول شمعة («قسم 6/4 **افتتاح 3.72** — اعلى 4.58» HTCR ⇒ صعود 23% =
        # هادئ · «قسم 11/12 **افتتاح 3.69** — اعلى 7.19» BNKK ⇒ 95% = انضخّ).
        first_val = _event_day_open(df.get("Open"), ev_date)
        # ⚠️ **NaN ليس None** (ثغرة لقّاها التدقيق الخصومي 2026-07-27): تنظيف البيانات
        # يُسقط الشموع بإغلاق مفقود فقط، فقد ينجو افتتاح NaN. و`not (nan and nan>0 …)`
        # يعطي True ⇒ **بوّابة «لم يصعد» تفشل مفتوحةً** فيمرّ مقسّم انضخّ +95%. نعامل
        # NaN معاملة الغياب ونرتدّ للإغلاق (السلوك السابق).
        if first_val is None or first_val != first_val:
            first_val = _split_day_value(close, splits, cut)
        if first_val is not None and first_val != first_val:
            first_val = None                     # الإغلاق نفسه تالف ⇒ لا قاعدة
        # ⚠️ **القرار على القيمة الخام، والتدوير للعرض فقط** (تدقيق 2026-07-27):
        # كنت أدوّر **قبل** المقارنة، فصعودٌ خام في (20.00%، 20.05%] يُدوَّر إلى 20.0
        # فلا يتجاوز الحدّ ⇒ **ينقلب من مرفوض إلى مقبول** = توسيعٌ صامت لعتبة فيصل
        # خلافًا لتوثيقي نفسه («العتبة لا تُمَسّ، والإبلاغ يكفي»).
        rose_raw = ((ref / first_val - 1.0) * 100.0
                    if first_val and first_val > 0 else None)
        didnt_rise = not (rose_raw is not None
                          and rose_raw > CONFIG["SPLIT_ROSE_MAX_PCT"])
        rose_pct = round(rose_raw, 1) if rose_raw is not None else None
        return {"event_kind": ev_kind, "event_date": str(ev_date),
                "split_date": str(ev_date), "ref": round(ref, 2),
                "half": half, "price": round(price, 2),
                "near_bottom": bool(near_bottom), "held_ok": bool(held_ok),
                # `rose_pct` **تشخيصي فقط** (لا يدخل أي قرار): يسمح بالإبلاغ عن
                # «قريب من الشرط» بدل الإسقاط الصامت — HTCR ‏+23% مقابل حدّ 20%.
                "rose_pct": rose_pct,
                "didnt_rise": bool(didnt_rise), "first_val": round(first_val, 2)
                if first_val else None,
                "freq": _split_frequency(splits, today)}
    except Exception:
        return None


def scan_split_radar(history, exclude=None, fetch_splits=None, fetch_borrow=None,
                     fetch_float=None, fetch_pump=None, cap=None):
    """🎯 رادار أسهم التقسيم (فيصل — عرض/سياق فقط، **خارج الفرز نهائيًا**): يمسح السوق
    عن مقسّمة عكسيًّا وصلت قاع «القمة÷2» وطابقت setup فيصل (IMG_0151: فلوت<2م · شورت
    <20ألف · حافظت 3 جلسات · خالية من القروبات · هدف 100%+) **و«لم تصعد أكثر من 20%»
    بعد الحدث** (‏`IMG_0153` — أُضيفت بأمر المالك 2026-08-13 «صلّح الرادار» بعد أن كُشف
    أن الرادار كان يتخطّاها وحدَه فيعرض ما يرفضه الصيّاد ⇒ الآن **ستّةٌ لا خمس**).
    لا يمسّ الاختيار/الدخول/
    الوقف/العضوية — تنبيه «لا يفوتك مقسّم» فقط. **بوّابة تكلفة**: مُرشّح OHLCV رخيص أولًا
    (سعر منخفض + كليف هبوط حادّ حديث = بصمة التقسيم المعدَّل) ثم جلب مقيَّد للتقسيمات/
    الاقتراض/الفلوت للمُرشّحين فقط. الجالبات محقونة للاختبار · فاشل-آمن مطلق.
    **🕵️ الشورت = عمود Available من ChartExchange** (`ce_borrow_info` — قراءة فيصل الموثّقة
    للشورت، IMG_9504-9506/9923: XHLD 600ألف «طاخ طيخ» · SPRC 10آلاف/705% · DSY 7آلاف) لا
    حجم FINRA اليومي (لا يغطّي هذي الأسهم المغمورة). M13 الفرزي يبقى على FINRA (قفل C3)."""
    exclude = exclude or set()
    fs = fetch_splits or _fetch_splits
    fb = fetch_borrow or ce_borrow_info    # فيصل: «الشورت» = المتاح للاقتراض (ChartExchange)
    today = dt.date.today()
    # 1) مُرشّح OHLCV رخيص (بلا شبكة): سعر منخفض + أعمق هبوط يوم حادّ في النافذة
    pre = []
    for sym, df in history.items():
        if sym in exclude:
            continue
        try:
            c = df["Close"].values.astype(float)
            if len(c) < 20:
                continue
            price = float(c[-1])
            if not (CONFIG["SPLIT_RADAR_PRICE_MIN"] <= price
                    <= CONFIG["SPLIT_RADAR_PRICE_MAX"]):
                continue
            look = min(int(CONFIG["SPLIT_LOOKBACK_DAYS"]), len(c) - 1)
            cliff = min((c[-k] / c[-k - 1] - 1.0)
                        for k in range(1, look + 1) if c[-k - 1] > 0)
            if cliff <= -CONFIG["SPLIT_CLIFF_PCT"] / 100.0:
                # 🔬 **T-CLIFF-2 (‏2026-08-06، أمرُ المالك «سوها»):** مفتاحُ ترتيبٍ
                #    بديلٌ **مطفأٌ افتراضيًّا**. حكمُ `T-CLIFF` نصَّ أن العلّة **مفتاحُ
                #    الترتيب والسقف** لا العتبة: الترتيبُ بعمق **كليف اليوم الواحد**،
                #    و`EHGO` — الذي وُجدت `c3` لأجله — **ضحلُ الكليف بالتعريف** فيقع
                #    بذيل القائمة فيقصّه السقف. البديل: **الهبوطُ التراكميّ** على
                #    النافذة. `"cliff"` (الافتراض) = السلوكُ الحاليّ **حرفيًّا**.
                _cum = None
                if str(CONFIG.get("SPLIT_RADAR_ORDER", "cliff")) == "cum":
                    try:
                        _hi = max(c[-look - 1:])
                        _cum = (price / _hi - 1.0) if _hi > 0 else 0.0
                    except (ValueError, ZeroDivisionError):
                        _cum = 0.0
                pre.append((sym, cliff if _cum is None else _cum))
        except Exception:
            continue
    if not pre:
        return []
    pre.sort(key=lambda x: x[1])           # الأعمق (كليفًا أو تراكميًّا) أولًا
    pre = [s for s, _ in pre[:int(CONFIG["SPLIT_RADAR_PROBE_CAP"])]]
    # 2) تأكيد التقسيم + المِجَسّ (جلب تقسيمات مقيَّد على المُرشّحين فقط)
    probed = []
    for sym in pre:
        try:
            pr = _split_setup_probe(history[sym], fs(sym), today)
            if pr and pr["near_bottom"]:
                pr["symbol"] = sym
                probed.append(pr)
        except Exception:
            continue
    if not probed:
        return []
    # 3) إثراء مقيَّد (اقتراض/متاح ChartExchange + فلوت + قروب) للمؤكَّدين فقط — معايير فيصل
    for p in probed:
        sym = p["symbol"]
        # 🕵️ «الشورت» بقراءة فيصل = عمود Available من ChartExchange (المتاح للاقتراض)
        bor = {}
        if fb:
            try:
                bor = fb(sym) or {}
            except Exception:
                bor = {}
        av = bor.get("shares_available")
        p["short"] = av
        p["borrow_fee"] = bor.get("borrow_fee")
        p["short_ok"] = (av is not None and av < CONFIG["SHORT_DAILY_MAX"])
        flt = None
        if fetch_float:
            try:
                flt = fetch_float(sym)
            except Exception:
                flt = None
        p["float"] = flt
        p["float_ok"] = (flt is not None and flt < CONFIG["SPLIT_RADAR_FLOAT_MAX"])
        pump = None
        if fetch_pump:
            try:
                pump = fetch_pump(history[sym])
            except Exception:
                pump = None
        p["pump"] = bool(pump and pump.get("found"))
        # درجة تطابق setup فيصل (عدد المعايير المتحقّقة، عرض/ترتيب فقط — ليست بوّابة)
        # 🔴 **صارت 0-6 بأمر المالك 2026-08-13:** أُضيف `didnt_rise` (نصُّ فيصل) بعد
        #    أن كان الرادارُ يتخطّاه. ⇒ **جاهز ⟺ match == 6**، والرتبةُ محفوظة:
        #    الجاهزُ يبقى في القمّة فلا يقصّه `SPLIT_RADAR_MAX` (كان جاهز ⟺ 5).
        p["match"] = int(p["near_bottom"]) + int(p["held_ok"]) + int(p["short_ok"]) \
            + int(p["float_ok"]) + int(not p["pump"]) + int(bool(p.get("didnt_rise")))
    probed.sort(key=lambda x: (-x["match"], x.get("freq", 0)))
    # 🔴 **السقفُ لا يقصّ جاهزًا أبدًا (إصلاح 2026-08-13، أمرُ المالك «صلّح كل شي متأكد
    #    منه»)** — كان مُبلَّغًا بلا إصلاح: `SPLIT_RADAR_MAX` يُطبَّق **قبل** الجاهزية،
    #    فلو تجاوز الجاهزون السقفَ يومًا **قُصَّ أحدُهم صامتًا** — وهو بالضبط ما تمنعه
    #    قاعدتُنا «لا قصَّ صامتًا». عمليًّا لم يقع (الجاهزُ يتصدّر بالفرز) **لكن
    #    «لم يقع» ليست حارسًا**. ⇒ الجاهزون (‏`match`==6) يمرّون كلُّهم، والسقفُ يحكم
    #    البقيّةَ وحدها. ⚠️ **يُشدّد لا يُرخي**: لا يُدخل صفًّا غيرَ جاهز، وأقصى أثره
    #    **إظهارُ جاهزٍ كان يُحذَف** — والترتيبُ محفوظ (الجاهزون أوّلًا كما هم).
    lim = int(cap or CONFIG["SPLIT_RADAR_MAX"])
    ready = [p for p in probed if p["match"] == 6]
    rest = [p for p in probed if p["match"] != 6]
    return ready + rest[:max(0, lim - len(ready))]


def _float_too_big(fl) -> bool:
    """🔴 هل الفلوت **معلوم وكبير**؟ (حدّ M14). المرجع الوحيد لقرار «مستبعد تماما»
    (المالك 2026-07-29) خارج البوّابة نفسها — يستعمله مسار الحمل وطبقة العرض فلا
    يتفرّق المعيار في ثلاثة أماكن. **فاشل-آمن:** مجهول/تالف/NaN ⇒ False (يمرّ
    بفائدة الشك، القاعدة المحسومة: تعذّر ≠ كبير)."""
    try:
        if fl is None:
            return False
        v = float(fl)
        return v == v and v >= CONFIG["FLOAT_GATE_MAX"]      # v==v يستبعد NaN
    except (TypeError, ValueError):
        return False


def split_radar_ready(rows: list) -> list:
    """✅ **المطابق الكامل فقط** (قرار المالك 2026-07-29: «ما ابي يجيني اشعار نهائيًّا
    إلا بالأسهم الجاهزة فقط»). كان الرادار يُرسل 12 سهمًا أغلبها بـ❌ — ضجيج يدفن
    الجاهز.

    🔴 **تصحيحٌ بأمر المالك 2026-08-13 («صلّح الرادار») — العيبُ الذي أُصلح:** كان
    الجاهزُ **خمسًا من ستّ**: قرب القاع÷2 · حافظ 3ج · شورت (متاح CE) · فلوت<2م ·
    خالٍ من قروب — **و«لم يصعد أكثر من 20%» غائبةٌ كليًّا** مع أنها **نصُّ فيصل
    حرفيًّا** (`IMG_0153`: «شرط ما تجاوز 20٪ اثناء الصعود» · وسمُ الدفتر
    `faisal_verbatim`) وتُحسب في `_split_setup_probe` وتُشترَط في `scan_split_hunter`.
    ⇒ فكانت الترويسةُ «المطابق الكامل» **تَعِد بأكثر مما تفحص** = عينُ عيب «كرت
    البوّابات» الذي أمسكه المالك (إطارٌ يكذب على قارئه). **وأثرُه مقيسٌ حيًّا:**
    ليلةَ 2026-08-12 عرض الرادارُ `LZMH` و`CHSN` **والصيّادُ صامت** — والفرقُ
    البنيويُّ الوحيدُ بينهما هذي الشرط.
    ⚖️ **والمقايضةُ كانت مقلوبة:** يرفض على **المتاح للاقتراض** (متغيّرٌ يتحرّك خمسَ
    مراتب يوميًّا بالمقيس) ويتساهل في **شرط فيصل الثابت** — والصيّادُ يفعل العكس.

    ⇒ الجاهز الآن = **الستّة كلها**. دالّة نقيّة، لا تُسقط معيارًا ولا تخترع واحدًا —
    نفس الستّة التي تُحسب في `scan_split_radar` (`match` صار 0-6 ⇒ **جاهز ⟺ 6**).
    🔒 و`didnt_rise` تُقرأ بنفس التحقّق البسيط كالخمسة (اتّساقُ نمط)، **ومفتاحُها
    مضمونُ الحضور** من `_split_setup_probe` دائمًا (فاشلةٌ-آمنة داخلها: بلا قيمةِ
    شمعةٍ ⇒ `True`) ⇒ **يستحيل أن تقصّ مرشّحًا حقيقيًّا بصمت** — مقفولٌ `RDR6ج`."""
    return [r for r in (rows or [])
            if r.get("near_bottom") and r.get("held_ok") and r.get("short_ok")
            and r.get("float_ok") and not r.get("pump")
            and r.get("didnt_rise")]      # ④ نصُّ فيصل — كانت غائبةً حتى 2026-08-13


def build_split_radar_section(rows: list) -> str:
    """قسم «🎯 رادار أسهم التقسيم» (فيصل — عرض/سياق فقط، خارج قائمة الترشيح):
    يعرض المقسّمة التي وصلت قاع القمة÷2 وحالة معايير فيصل (فلوت/شورت/ثبات/قروب/
    **لم يصعد**).
    🔴 **لا يُرسَل إلا المطابق الكامل** (قرار المالك 2026-07-29) — وغيابُه صمتٌ تامّ
    (رسالة فارغة ⇒ `send_telegram` لا يُنادى أصلًا في مسار الإرسال).
    ✅ **و«الكامل» صار صادقًا فعلًا (2026-08-13، أمرُ المالك «صلّح الرادار»):** كان
    يفحص **خمسًا من ستّ** ويُسمّي نفسَه «الكامل» — فأُضيف شرطُ فيصل ④ إلى
    `split_radar_ready`، **ويُطبَع صراحةً برقمه** في سطرٍ مستقلّ فلا تبقى الترويسةُ
    دعوًى بلا شاهد (درسُ «سطرُ عرضٍ بلا حقلٍ = كذبة» معكوسًا: **شرطٌ بلا سطرٍ = دعوًى
    غيرُ قابلةٍ للفحص**)."""
    rows = split_radar_ready(rows)
    if not rows:
        return ""

    def chk(ok):
        return "✅" if ok else "❌"

    lines = ["🎯 <b>رادار أسهم التقسيم</b> (فيصل: القاع = قمة ما بعد التقسيم ÷2) — "
             "<b>المطابق الكامل فقط</b>:"]
    for r in rows:
        flt = fmt_money(r["float"]) if r.get("float") is not None else "—"
        # 🕵️ «الشورت» = المتاح للاقتراض من ChartExchange (قراءة فيصل) + الرسوم لو متاحة
        srt = fmt_money(r["short"]) if r.get("short") is not None else "—"
        fee = (f" · رسوم {r['borrow_fee']:.0f}%"
               if r.get("borrow_fee") is not None else "")
        lines.append(f"• <b>{esc(r['symbol'])}</b> ${r['price']:.2f} · "
                     f"هدف القاع ÷2 = ${r['half']:.2f} (قمة ما بعد التقسيم {r['ref']:.2f})")
        lines.append(f"  {chk(r.get('float_ok'))} فلوت {flt} (تحت 2م) · "
                     f"{chk(r.get('short_ok'))} شورت (متاح CE) {srt} (تحت 20ألف){fee} · "
                     f"{chk(r.get('held_ok'))} حافظ 3ج · "
                     f"{chk(not r.get('pump'))} خالٍ من قروب")
        # ④ نصُّ فيصل «شرط ما تجاوز 20٪ اثناء الصعود» — **يُطبَع برقمه** فلا تبقى
        #   ترويسةُ «المطابق الكامل» دعوًى بلا شاهد (أُضيف 2026-08-13 مع الشرط نفسه).
        _rp = r.get("rose_pct")
        lines.append(f"  {chk(r.get('didnt_rise'))} لم يصعد بعد الحدث "
                     + (f"{_rp:.0f}%" if isinstance(_rp, (int, float))
                        else "—")
                     + f" (شرط فيصل: لا يتجاوز "
                       f"{CONFIG['SPLIT_ROSE_MAX_PCT']:.0f}%)")
        fl = _split_freq_line(r.get("freq"))
        if fl:
            lines.append("  " + fl)
    lines.append("<i>عرض/سياق فقط — خارج قائمة الترشيح (فيصل IMG_0151: "
                 "متوسط حركة 30-50 · هدف 100%+).</i>")
    return _rtl_join(lines)


def _yahoo_float(sym: str, strict: bool = False):
    """فلوت ياهو (المصدر الأساسي للفلوت — صفحة CE overview صارت قِشرة JS 2026-07-24
    فماتت `ce_float_info`؛ مُجسّ Actions أثبت ياهو يعطي الفلوت للميكروكاب المغمورة:
    JEM 93,759). يرجّع `floatShares` (المفضّل) وإلا `sharesOutstanding`، أو None.
    فاشل-آمن · عرض/سياق فقط — خارج الفرز (M14 لا تُمسّ).

    ⚠️ **`strict=True` (أُضيف 2026-07-28، خطة `plans/003`): `floatShares` حصرًا.**
    السقوط لـ`sharesOutstanding` **تقريب** (وهو دائمًا ≥ الفلوت لأنه يشمل المقيَّد)،
    ومقبول لأدوات العرض (صيّاد/رادار التقسيم: يجعلها أشدّ لا أرخى). لكنه **ممنوع**
    في أي حقل يصل `refloat_gate_recheck` — فهي تُعيد حكم M14 على `r["float"]` في
    **مسار الاختيار**، فتقريبٌ أعلى من الحقيقة = تشديد صامت للبوّابة (مُستنسَخ: قيمة
    277م من `sharesOutstanding` وحده وُسمت «فلوت كبير»). ⇒ **كل نقطة يصل مخرجُها
    إلى الاختيار تستعمل `strict=True`.**"""
    try:
        if yf is None:
            return None
        info = yf.Ticker(sym).info or {}
        if strict:
            return info.get("floatShares")
        return info.get("floatShares") or info.get("sharesOutstanding")
    except Exception:
        return None


def operator_sustain(bars, break_level, min_minutes=None):
    """⏱️ **قاعدة «ربع الساعة»** (فيصل، JZ فريم الساعة IMG_0294، 2026-07-27): «هذي شمعة الهمل
    اللي خربت السهم ضغطه المضارب — **لو كان مضارب يعطيك مجال تبيع وتذبذب يصل مداه أكثر من ربع
    ساعه** — طلع السهم **بدون اذن مضارب** ضغطه المضارب للهاويه».

    ⇒ **معيار زمني يميّز الرفعة المأذونة (مضارب) عن غير المأذونة (قروب):** المضارب يترك مجالًا
    للبيع فيصمد التذبذب **≥15 دقيقة**؛ والرفعة بلا إذنه تُسحق فورًا. وهو **الميكانيكا** خلف
    قاعدة JZ اليومية «لما يحصل قروب يرفع السهم المضارب يلغي الاهداف ويهبط فيه» (`pump_voids_targets_line`).

    يأخذ شموع الدقيقة **بعد** الاشتعال ومستوى الكسر، ويرجّع:
    `{minutes, ok}` — `minutes` = عدد دقائق الصمود المتصل فوق مستوى الكسر من البداية،
    `ok` = بلغ `OPERATOR_SUSTAIN_MIN` (15) فأكثر. None لو مدخلات غير صالحة.

    نقيّة · فاشلة-آمنة · **قياس/تشخيص فقط**: لا تكبت تنبيهًا ولا تدخل الفرز — تُستهلك في طبقة
    قياس الرادار (مسار الدقيقة المردوم بعد التنبيه) لتصنيف الإطلاق «مضارب» مقابل «قروب»."""
    try:
        if not bars or not break_level or float(break_level) <= 0:
            return None
        lvl = float(break_level)
        n = 0
        for b in bars:
            c = b.get("c", b.get("close")) if isinstance(b, dict) else b
            if c is None:
                break
            if float(c) < lvl:          # كُسر لتحت = انتهى الصمود
                break
            n += 1
        need = int(min_minutes if min_minutes is not None
                   else CONFIG["OPERATOR_SUSTAIN_MIN"])
        return {"minutes": n, "ok": n >= need}
    except Exception:
        return None


def split_ma_maturity(df, split_date, period=30):
    """📏 **«حقق متوسط N يوم من تاريخ التقسيم»** (فيصل — LABT IMG_0303، 2026-07-27): «السهم هذا
    **مقسم في 22-6** … امس التاريخ 22-7 … **حقق متوسط 30 يوم من تاريخ التقسيم**».

    ⚠️ **الرقم ليس واحدًا** (مسح الصور الثاني 2026-07-27): فيصل يذكر **30** (LABT) و**40**
    (JEM IMG_0141 «إذا حقق متوسط 40 يوم ✅») و**50** — وهي مجموعته الموثّقة نفسها
    (IMG_0151: «متوسطات 20<30<50»). فالدالّة تبقى عامّة بـ`period`، و`split_ma_lines`
    تعرض **المجموعة** (`SPLIT_MA_PERIODS`) بدل رقم مُفرَد يُوهم أنه الرقم الوحيد.

    الفكرة: بعد التقسيم العكسي يبقى المتوسط **غير ناضج** حتى تمرّ `period` جلسة **منذ التقسيم**
    (قبلها نافذته تخلط ما قبل التقسيم وما بعده)، وبلوغ السعر لهذا المتوسط الناضج = إشارة فيصل.

    يرجّع `{sessions, mature, ma, reclaimed}`: عدد الجلسات منذ التقسيم · هل نضج (≥period) ·
    قيمة المتوسط على شموع **ما بعد التقسيم حصرًا** (None قبل النضج) · هل السعر بلغه/تجاوزه.
    None لو تعذّر. نقيّ · فاشل-آمن · **عرض/سياق فقط — خارج الفرز** (لا يُسقط سهمًا ولا يرشّحه)."""
    try:
        if df is None or split_date is None or len(df) < 5:
            return None
        d = split_date
        if hasattr(d, "date"):
            d = d.date()
        if isinstance(d, str):
            d = dt.date.fromisoformat(d[:10])
        idx = df.index
        days = [(t.date() if hasattr(t, "date") else t) for t in idx]
        after = [i for i, x in enumerate(days) if x >= d]
        if not after:
            return None
        seg = df["Close"].iloc[after[0]:].values.astype(float)
        n = len(seg)
        out = {"sessions": n, "mature": n >= int(period), "ma": None,
               "reclaimed": None}
        if out["mature"]:
            ma = float(np.mean(seg[-int(period):]))
            out["ma"] = round(ma, 2)
            out["reclaimed"] = bool(seg[-1] >= ma)
        return out
    except Exception:
        return None


def split_ma_line(m, period: int = 30) -> str:
    """سطر «متوسط N يوم من التقسيم» (عرض فقط). «» لو None."""
    if not m:
        return ""
    p = int(period)
    if not m.get("mature"):
        return (f"📏 متوسط {p}ي من التقسيم: <b>لم ينضج</b> "
                f"({m['sessions']} جلسة من {p} — فيصل يقيسه من تاريخ التقسيم)")
    tag = "✅ حقّقه" if m.get("reclaimed") else "⏳ تحته"
    return f"📏 متوسط {p}ي من التقسيم: ${m['ma']:.2f} — {tag}"


def split_ma_lines(df, split_date, periods=None) -> str:
    """📏 **مجموعة متوسطات فيصل من تاريخ التقسيم** (سطر واحد مُجمَّع، عرض فقط).

    فيصل يذكر أرقامًا مختلفة بحسب السهم — **30** (LABT) · **40** (JEM) · **50** — وهي
    مجموعته الموثّقة `20<30<50` (IMG_0151). فبدل انتقاء رقم واحد يُوهم أنه «القاعدة»،
    نعرضها كلها بنضجها: «📏 متوسطات من التقسيم (N جلسة): 20 ✅ $1.20 · 30 ⏳ $1.35 · 50 لم ينضج».

    نقيّ · فاشل-آمن → «». **عرض/سياق فقط — خارج الفرز.**"""
    try:
        ps = list(periods or CONFIG.get("SPLIT_MA_PERIODS") or (20, 30, 50))
        parts, sess = [], None
        for p in ps:
            m = split_ma_maturity(df, split_date, period=p)
            if not m:
                continue
            sess = m["sessions"]
            if not m.get("mature"):
                parts.append(f"{p} <b>لم ينضج</b>")
            else:
                parts.append(f"{p} {'✅' if m.get('reclaimed') else '⏳'} "
                             f"${m['ma']:.2f}")
        if not parts:
            return ""
        return (f"📏 متوسطات من التقسيم ({sess} جلسة): " + " · ".join(parts)
                + " — فيصل يقيسها من تاريخ التقسيم (30 LABT · 40 JEM · 50)")
    except Exception:                                    # noqa: BLE001
        return ""


def _resample_minute_bars(bars, k: int):
    """يجمّع شموع الدقيقة إلى شموع k-دقيقة (تجميع متتالٍ بسيط). نقيّ · فاشل-آمن → []."""
    out = []
    try:
        k = max(1, int(k))
        for i in range(0, len(bars) - k + 1, k):
            g = bars[i:i + k]
            los = [float(b.get("l", b.get("low"))) for b in g
                   if b.get("l", b.get("low")) is not None]
            his = [float(b.get("h", b.get("high"))) for b in g
                   if b.get("h", b.get("high")) is not None]
            cs = [float(b.get("c", b.get("close"))) for b in g
                  if b.get("c", b.get("close")) is not None]
            if not los or not his or not cs:
                continue
            out.append({"l": min(los), "h": max(his), "c": cs[-1]})
    except Exception:
        return []
    return out


def rebound_entry_state(bars, frames=(5, 15, 30), tol_pct=1.5, look_minutes=180,
                        touch_tol_pct=1.0, sep=2, min_rise_pct=None):
    """⭐ **استراتيجية «اتفاق الفريمات» وصيد الارتداد** (IMG_0305/0306، 2026-07-27):

    ⚠️ **حدّ مصدر (تدقيق تعارض 2026-07-27):** رأس المنشور: «شرح سابق للدكتور فيصل لسهم سابق
    **(مع بعض الاضافات من باب النصح لكم)**» — أي **قناة تعليمية تعيد شرحه بإضافاتها**، لا نصّ فيصل
    الحرفي. فتُعامَل **أدنى ثقة** من تغريداته المباشرة.

    ⚠️ **نظامٌ مختلف عن الارتكاز — لا يُخلط:** شرطها المكتوب على الشارت «**شرط السهم محقق ارتفاع +
    سيوله عاليه**» = **مضاربة زخم على سهم صعد بقوة ثم ارتدّ** (8.30→13.54→ارتداد 10.21→14.70)،
    بينما **سهم الارتكاز عند قاعه لم يصعد أصلًا**. لذلك:
      • `min_rise_pct` (افتراضه `REBOUND_MIN_RISE_PCT`) **بوّابة سياق إلزامية**: بلا صعود سابق
        داخل النافذة لا تُعطى إشارة دخول (`context_ok=False`) — منعًا لتطبيقها على قاع راكد.
      • **لا تُستعمل للاختيار ولا تلغي منهجية الارتكاز** — طبقة توقيت/خروج مساندة فقط.
      • علاقتها بقاعدة فيصل الموثّقة «لا تدخل الدعم الأول» = **تشابه لا تطابق** (سياق مختلف).

      «فكرة الحركة: السهم بعد كل صعود قوي لازم يجني ربحه وينزل… تنتظر السهم يهدأ ويثبت على دعومه.
       **السر (اتفاق الفريمات): تفتح الشارت على 5 دقائق و15 و30 — إذا الثلاثة متفقة وثابتة على نفس
       الدعم، اعرف إن الارتداد قريب وقوي.** … ارتد منه صعودًا لـ11.46 ورجع **مرة ثانية** يختبر نفس
       الدعم 10.21 وثبت فوقه. **هنا مكان الدخول: فورًا مع الارتداد الثاني والثبات** (بعدها 14.70 =
       ربح 45%). **الخروج: إذا كسر السعر منطقة الدعم وقفل تحتها اطلع فورًا.**»

    وعلى الشارت: «**ارتداد أول عدم دخول**» · «**ارتداد 2 تأكيد دخول عدم كسر**» · «فريم 5 دقايق
    **شرط السهم محقق ارتفاع + سيوله عاليه**» · «**رأس شمعة الهبوط جني الربح عند ارتداده لها**».

    ⇒ يُكمِّم قاعدتنا الموثّقة «لا تدخل الدعم الأول» برقم صريح: **الأول لا · الثاني نعم**. ويضيف
    بُعدًا مفقودًا: **فريمات لحظية (5/15/30د)** — فريماتنا كانت شهري/أسبوعي/يومي فقط.

    يأخذ شموع الدقيقة ويرجّع:
    `{support, agree, frames, bounces, holding, rise_pct, context_ok, entry}` — `agree` = الفريمات
    الثلاثة على نفس الدعم ضمن `tol_pct`% · `bounces` = لمسات الدعم المستقلّة · `holding` = آخر إغلاق
    فوقه · `rise_pct` = الصعود داخل النافذة · `context_ok` = تحقّق شرط «محقق ارتفاع» ·
    `entry` = **السياق + الاتفاق + ارتدادان فأكثر + ثبات**. None لو العيّنة قصيرة.

    نقيّ · فاشل-آمن · **عرض/تشخيص فقط** — لا يفتح صفقة ولا يمسّ الفرز ولا التنبيه."""
    try:
        if not bars or len(bars) < max(frames) * 3:
            return None
        # ⚠️ النافذة **زمنية موحّدة** لا «عدد شموع»: 12 شمعة على 5د = ساعة بينما على 30د = 6
        # ساعات، فتنظر الفريمات لمناطق مختلفة ويسقط الاتفاق زورًا. «اتفاق الفريمات» عند فيصل =
        # نفس منطقة الشارت بثلاث دقّات (اكتشفه اختبار سيناريو 10.21 الحقيقي).
        sups, frames_used = [], []
        for k in frames:
            rb = _resample_minute_bars(bars, k)
            if len(rb) < 4:
                return None
            seg = rb[-max(4, int(look_minutes) // int(k)):]
            sups.append(min(b["l"] for b in seg))
            frames_used.append(k)
        lo_s, hi_s = min(sups), max(sups)
        if lo_s <= 0:
            return None
        agree = ((hi_s / lo_s - 1.0) * 100.0) <= float(tol_pct)
        support = round(lo_s, 2)
        # عدّ الارتدادات المستقلّة عن الدعم على فريم 5د (لمسة ثم ابتعاد)
        five = _resample_minute_bars(bars, frames[0])
        band = lo_s * (1.0 + touch_tol_pct / 100.0)
        bounces, last = 0, -10_000
        for i, b in enumerate(five):
            if b["l"] <= band:
                if i - last >= sep:
                    bounces += 1
                last = i
        holding = bool(five and five[-1]["c"] > lo_s)
        # 🚧 بوّابة السياق: «شرط السهم محقق ارتفاع» — الاستراتيجية لسهم صعد بقوة ثم ارتدّ،
        # لا لسهم ارتكاز راكد عند قاعه (تدقيق التعارض 2026-07-27).
        hi_w = max((b["h"] for b in five), default=0.0)
        rise_pct = round((hi_w / lo_s - 1.0) * 100.0, 1) if lo_s > 0 else 0.0
        need_rise = float(min_rise_pct if min_rise_pct is not None
                          else CONFIG["REBOUND_MIN_RISE_PCT"])
        context_ok = rise_pct >= need_rise
        return {"support": support, "agree": bool(agree), "frames": frames_used,
                "bounces": bounces, "holding": holding, "rise_pct": rise_pct,
                "context_ok": bool(context_ok),
                "entry": bool(context_ok and agree and bounces >= 2 and holding)}
    except Exception:
        return None


def rebound_entry_line(st) -> str:
    """سطر «اتفاق الفريمات / صيد الارتداد» (عرض فقط). «» لو None."""
    if not st:
        return ""
    fr = "+".join(f"{f}د" for f in st.get("frames", []))
    # 🚧 خارج السياق: استراتيجية زخم لسهم صعد بقوة — لا تُطبَّق على قاع ارتكاز راكد.
    if not st.get("context_ok", True):
        return ("ℹ️ صيد الارتداد (5/15/30د) <b>لا ينطبق</b>: استراتيجية زخم تشترط سهمًا "
                f"«محقق ارتفاع» (الصعود بالنافذة {st.get('rise_pct', 0):.0f}% فقط) — "
                "منهجية الارتكاز عند القاع منفصلة")
    if st.get("entry"):
        return (f"🎯 <b>ارتداد 2 مؤكَّد</b> عند ${st['support']:.2f} — الفريمات ({fr}) "
                "متفقة وثابتة · فيصل: <b>الدخول هنا</b> (الوقف: إغلاق تحته)")
    # ⚠️ الكسر **أولًا**: هو الحدث الأخطر (خروج فوري)، وكان يُحجب خلف فرع «الارتداد الأول».
    if not st.get("holding"):
        return f"⛔ كسر الدعم ${st['support']:.2f} — فيصل: «كسر وقفل تحتها اطلع فورًا»"
    if st.get("agree") and st.get("bounces", 0) <= 1:
        return (f"⏳ الفريمات ({fr}) متفقة على ${st['support']:.2f} — "
                "لكنه <b>الارتداد الأول: لا دخول</b> (فيصل: انتظر الثاني)")
    return (f"👀 الفريمات ({fr}) غير متفقة بعد (دعم ${st['support']:.2f} · "
            f"ارتدادات {st.get('bounces', 0)}) — لا إشارة ارتداد")


def bottom_test_state(df, lookback=60, tol_pct=3.0, sep=3):
    """🔁 **حالة «القاع 2»** (فيصل، EDBL IMG_0298: «تم التلاعب بالشموع أكثر من مرة — **القاع 2 =
    ثبات أو سحب سيوله** — متابعه فقط» · EZRA IMG_0295: «قاع جديد بعد تلاعب بالشموع · **متابعة 2
    هل يثبت أو يكون قاع جديد**»).

    يعدّ كم مرّة اختبر السعرُ القاعَ (لمسات ضمن `tol_pct`% منه، يفصلها `sep` جلسات = لمسة مستقلة).
    الاختبار **الثاني فأكثر** = مفترق ثنائي معلن: **ثبات** أو **سحب سيولة** (نطاق −7%..−13%).
    يرجّع {bottom, tests, second} أو None. نقيّ · فاشل-آمن · **عرض/سياق فقط**."""
    try:
        lows = df["Low"].tail(lookback).values.astype(float)
        if len(lows) < 10:
            return None
        bot = float(np.min(lows))
        if bot <= 0:
            return None
        band = bot * (1.0 + tol_pct / 100.0)
        tests, last = 0, -10_000
        for i, x in enumerate(lows):
            if float(x) <= band:
                if i - last >= sep:
                    tests += 1
                last = i
        return {"bottom": round(bot, 2), "tests": tests, "second": tests >= 2}
    except Exception:
        return None


def bottom_test_line(bt, sweep_zone=None) -> str:
    """سطر «القاع 2» (عرض فقط). «» لو لا اختبار ثانٍ."""
    if not bt or not bt.get("second"):
        return ""
    z = ""
    if sweep_zone and sweep_zone.get("shallow") and sweep_zone.get("deep"):
        z = (f" (سحب السيولة ${sweep_zone['shallow']:.2f} → "
             f"${sweep_zone['deep']:.2f})")
    return (f"🔁 القاع اختُبر {bt['tests']} مرات عند ${bt['bottom']:.2f} — "
            f"فيصل: «القاع 2 = ثبات أو سحب سيولة»{z}")


def pump_repeat_watch_only(r) -> str:
    """🚫 **قاعدة «رُفِع أكثر من مرة بدون مضارب ⇒ متابعة فقط»** (فيصل — EZRA IMG_0295: «معروف عند
    الجميع و**تم رفعه أكثر من مرة بدون مضارب** … **متابعه فقط**» · EDBL IMG_0298: «**تم التلاعب
    بالشموع أكثر من مرة** … متابعه فقط»).

    القرينة المرصودة لـ«رفعة بلا مضارب» = **بصمة رفعة القروب المتكرّرة** (`group_pump_scar`:
    قفزة + سيولة عالية ثم كسر الدعم) — فتكرارها **مرّتين فأكثر** يُنزِّل السهم إلى «متابعة فقط».
    ⚠️ **حدّ صدق مصرَّح به:** «بدون مضارب» استدلال من البصمة المتكرّرة لا قياس مباشر لهوية المشتري.
    سطر **عرض/تحذير فقط** — لا يُسقط سهمًا من الفرز ولا يغيّر أهدافًا. فارغ لو أقل من رفعتين."""
    try:
        ps = r.get("pump_scar") or {}
        n = int(ps.get("n_pumps") or 0)
        if ps.get("found") and n >= 2:
            return (f"🚫 رُفِع {n} مرات بلا بصمة مضارب — فيصل: <b>متابعة فقط</b> "
                    "(مرفوع بالقروب، لا دخول)")
    except Exception:
        pass
    return ""


def pump_voids_targets_line(r) -> str:
    """⚠️ **قاعدة فيصل: القروب يُلغي الأهداف** (JZ IMG_0289، 2026-07-27): «الاصل هذي اهداف
    السهم 12 شمعه ساقطه — **لما يحصل قروب يرفع السهم المضارب يلغي الاهداف ويهبط فيه**».
    فرفعة القروب المرصودة (`group_pump_scar`, القرينة N1) **تُبطل سلّم الأهداف** لا تُضعفه
    فقط — وكنّا نعرض الأهداف كما هي بلا هذا التحفّظ. سطر **عرض/تحذير فقط**: لا يغيّر الأهداف
    ولا الوقف ولا الاختيار. فارغ لو لا رفعة قروب · نقيّ · فاشل-آمن."""
    try:
        if (r.get("pump_scar") or {}).get("found"):
            return ("⚠️ رفعة قروب سابقة — فيصل: المضارب <b>يُلغي الأهداف</b> ويهبط فيه "
                    "(سلّم الأهداف أعلاه غير معتمد)")
    except Exception:
        pass
    return ""


def faisal_split_plan(df, price, bottom=None, resist=None, heads=None, gap=None,
                      sweep_pct=None):
    """🥇 **خطة فيصل لسهم التقسيم** — مستخلَصة من رسالته الحيّة على $ONCO (2026-07-24،
    السهم الذي رشّحه صيّادنا فحلّله فيصل ودخله؛ أرقامه طابقت مِجَسّنا حرفيًّا: «1.44 أعلى
    شمعة بعد التقسيم ÷2 = 72» = `_post_split_high`، و«شورت 150 ألف» = المتاح CE).

    كان الصيّاد يعرض القاع÷2 و«هدف +100%» المجرّد فقط، بينما خطة فيصل التنفيذية أربعة أرقام:
      ① **التحرر** «ثبات فوق 92 سنت تحرر السهم» = **أقرب** مقاومة حقيقية فوق السعر (0.82).
         ⚠️ غير `liberation` بالفارز (=أعلى مقاومة، بوابة الانطلاق النهائية) — هذا حاجز
         الاستعادة القريب الذي يفكّ الأسر، ومن فوقه تأتي الأهداف.
      ② **الأهداف البنيوية** «1.19 راس الشمعه الساقطه هدف · 1.43 هدف» — رؤوس الشموع الحمرا
         (`_red_candle_heads`، قاعدة فيصل الموثّقة) ثم المقاومات، بدل «+100%» المجرّد.
      ③ **الفجوة السعرية** «فجوه سعريه من 1.88 ل 3» = أقرب فجوة غير مملوءة فوق السعر.
      ④ **سحب السيولة نطاقًا** — قاعدة فيصل الصريحة على CCHH (IMG_0297): «من القاع 1.30 سحب
         السيوله **متعارف عليه من 7٪ ل 13٪** · 1.30−10٪=1.17». فيُعرض **نطاق** [−7%، −13%]
         مع الأرجح −10% بدل رقم واحد (كانت 5% من حالة ONCO وحدها = أضيق من قاعدته المعلنة).
         `sweep_pct` صراحةً يعطي رقمًا مفردًا (لحالة ONCO الضحلة). فيصل يربط العمق بارتفاع الشورت.

    نقيّة · فاشلة-آمنة (أي عطل → مفاتيح None) · الحاقنات (`resist`/`heads`/`gap`/`bottom`)
    للاختبار فقط، والإنتاج يحسبها من `df`. **عرض/سياق فقط — خارج الفرز والجذور نهائيًّا.**"""
    out = {"liberation": None, "targets": [], "gap": None, "sweep": None,
           "sweep_zone": None, "bottom": None}
    try:
        price = float(price)
        if price <= 0:
            return out
        # ① القاع الفعلي (فيصل استعمل 0.71 = القاع المُحقَّق لا الـ÷2 النظري 0.72)
        if bottom is None and df is not None:
            low = df["Low"].tail(CONFIG["SPLIT_BOTTOM_LOOKBACK"]).values.astype(float)
            bottom = float(min(low)) if len(low) else None
        out["bottom"] = round(float(bottom), 2) if bottom else None
        # ② سحب السيولة: **نطاق** −7%..−13% والأرجح −10% (قاعدة فيصل المعلنة على CCHH)
        if bottom and float(bottom) > 0:
            _b = float(bottom)
            pct = float(sweep_pct if sweep_pct is not None
                        else CONFIG["SPLIT_SWEEP_MID_PCT"])
            out["sweep"] = round(_b * (1.0 - pct / 100.0), 2)
            out["sweep_zone"] = {
                "shallow": round(_b * (1.0 - CONFIG["SPLIT_SWEEP_MIN_PCT"] / 100.0), 2),
                "deep": round(_b * (1.0 - CONFIG["SPLIT_SWEEP_MAX_PCT"] / 100.0), 2)}
        # ③ المقاومات فوق السعر (أقربها = التحرر · ما فوقه = الأهداف)
        lv = sorted({round(float(x), 2) for x in
                     (resist if resist is not None else resistance_levels(df, price))
                     if float(x) > price})
        hd = {round(float(x), 2) for x in
              (heads if heads is not None
               else (_red_candle_heads(df, price) if df is not None else []))}
        if lv:
            out["liberation"] = lv[0]
            for t in lv[1:3]:                     # هدفان (فيصل: 1.19 ثم 1.43)
                out["targets"].append(
                    {"price": t,
                     "src": "رأس شمعة حمراء" if t in hd else "مقاومة"})
        # ④ أقرب فجوة غير مملوءة فوق السعر (فيصل: 1.88 → 3)
        z = gap if gap is not None else (all_unfilled_gaps_above(df) or {}).get("nearest")
        if z and z.get("bottom") and z.get("top"):
            out["gap"] = {"bottom": round(float(z["bottom"]), 2),
                          "top": round(float(z["top"]), 2)}
    except Exception:
        pass
    return out


_SPLIT_NEAR_MISS: list = []      # 🔔 آخر «قريبين من شرط لم يصعد» (تشخيص/ذيل تنبيه)


def scan_split_hunter(history, today=None, fetch_splits=None, fetch_float=None,
                      fetch_borrow=None, fetch_pump=None, fetch_offering=None):
    """🪝 صيّاد أسهم التقسيم (فيصل — **أداة مستقلة تمامًا عن فارز الارتكاز 14 بوابة**).
    يمسح السوق عن مقسّم عكسي يطابق setup فيصل **الصارم** ويرجع المطابقين الكاملين فقط.
    🆕 **2026-07-27:** الشرط ① صار «**حدث مؤسِّس** حديث» = تقسيم عكسي **أو طرح جديد**
    (بطاقة فيصل MWC تعامل الطرح كالقسم حرفيًّا). **الشروط الخمسة الأخرى لم تُمَسّ** —
    توسيع نوع الحدث لا تخفيف معيار. نداء SEC للطرح مقيَّد بـ`OFFERING_PROBE_CAP` ولا
    يقع إلا على مُرشّح OHLCV **بلا** تقسيم عكسي حديث (فصفر تكلفة على المقسّمين).
    **الشروط الصارمة (تُشترط كلها — قرار المستخدم «أساسي موثوق»):** ① حدثٌ مؤسِّس حديث
    ② وصل قمة-ما-بعد-الحدث÷2 ③ حافظ القاع 3 جلسات ④ فلوت<2مليون (ياهو، مثبَت) ⑤
    خالٍ من رفعة قروب ⑥ **«لم يصعد أكثر من `SPLIT_ROSE_MAX_PCT`% بعد الحدث»**
    (‏`IMG_0150/0153` — نصُّ فيصل، مُنفَّذةٌ في الكود أدناه: `if not pr["didnt_rise"]`).
    🔴 **وهذا النصُّ كان يسرد خمسًا والكودُ يشترط ستًّا** — عيبٌ مُبلَّغٌ 2026-08-13
    صباحًا وأُصلح مساءً بأمر المالك «صلّح كل شي متأكد منه». **تصحيحُ نصٍّ فقط: صفرُ
    تغييرٍ في السلوك** (جسمُ الدالّة byte-identical — مقفولٌ `SHDOC`)، والبصمةُ
    تُحدَّث **بإقرارٍ مؤرَّخ** لا بإرخاء.
    **السياق (عرض فقط، أفضل-جهد):** المتاح<20ألف + رسوم الاقتراض
    (ChartExchange، قد يتقطّع/يغيب) + متوسطات 20/30/50 + تكرار التقسيم. **لا يمسّ
    الاختيار/الدخول/الوقف/العضوية — تنبيه صيد فقط.** الجالبات محقونة للاختبار · فاشل-آمن."""
    fs = fetch_splits or _fetch_splits
    ff = fetch_float or _yahoo_float
    fb = fetch_borrow or ce_borrow_info
    fp = fetch_pump or group_pump_scar
    fo = fetch_offering or _offering_event      # 🆕 الحدث المؤسِّس البديل: طرح جديد
    today = today or dt.date.today()
    off_budget = [int(CONFIG["OFFERING_PROBE_CAP"])]
    near_miss = []          # 🔔 استوفى كل شيء وسقط على «لم يصعد» **بفارق قريب** فقط
    # 1) مُرشّح OHLCV رخيص (نفس رادار المقسّم): سعر منخفض + كليف هبوط حادّ حديث
    pre = []
    for sym, df in history.items():
        try:
            c = df["Close"].values.astype(float)
            if len(c) < 20:
                continue
            price = float(c[-1])
            if not (CONFIG["SPLIT_RADAR_PRICE_MIN"] <= price
                    <= CONFIG["SPLIT_RADAR_PRICE_MAX"]):
                continue
            look = min(int(CONFIG["SPLIT_LOOKBACK_DAYS"]), len(c) - 1)
            cliff = min((c[-k] / c[-k - 1] - 1.0)
                        for k in range(1, look + 1) if c[-k - 1] > 0)
            if cliff <= -CONFIG["SPLIT_CLIFF_PCT"] / 100.0:
                # 🔬 **T-CLIFF-2 (‏`cliff2_prereg.md`) — خطّافُ ترتيبٍ مطفأٌ افتراضيًّا.**
                # 🔴 وسببُ وجوده هنا **عيبٌ مقيس**: وضعتُه أوّلًا في `scan_split_radar`
                #    بينما أدواتُ T-CLIFF تقيس **هذي الدالّة** ⇒ خرجت ذراعُ الترتيب
                #    **مطابقةً بت-بت** لذراع الأساس = **no-op** كشفَته العدّادات لا
                #    القراءة. `"cliff"` (الافتراض) = السلوكُ الحاليّ **حرفيًّا**.
                _cum = None
                if str(CONFIG.get("SPLIT_RADAR_ORDER", "cliff")) == "cum":
                    try:
                        _hi = max(c[-look - 1:])
                        _cum = (price / _hi - 1.0) if _hi > 0 else 0.0
                    except (ValueError, ZeroDivisionError):
                        _cum = 0.0
                pre.append((sym, cliff if _cum is None else _cum))
        except Exception:
            continue
    pre.sort(key=lambda x: x[1])
    pre = [s for s, _ in pre[:int(CONFIG["SPLIT_RADAR_PROBE_CAP"])]]
    # 2) الشروط الصارمة الخمسة على المُرشّحين
    out = []
    for sym in pre:
        try:
            df = history[sym]
            sp = fs(sym)
            pr = _split_setup_probe(df, sp, today)   # ①②③⑥ مقسّم+÷2+حافظ3ج+لم يصعد
            # 🆕 لا تقسيم عكسي حديث ⇒ جرّب **الطرح الجديد** حدثًا مؤسِّسًا (بطاقة MWC).
            # نداء SEC مقيَّد بسقف صارم ولا يقع إلا على مُرشّح OHLCV اجتاز الكليف.
            if pr is None and off_budget[0] > 0:
                off_budget[0] -= 1
                ov = fo(sym, today=today)
                if ov:
                    pr = _split_setup_probe(df, sp, today, offering=ov)
                    if pr:
                        pr["event_form"] = ov.get("form")
            if not pr or not pr["near_bottom"] or not pr["held_ok"]:
                continue
            if not pr["didnt_rise"]:                     # ⑥ IMG_0150 «قسم ما أعطى صعود»
                # 🔔 **لا إسقاط صامت** (مبدأ «لا قصّ صامت»): من استوفى كل شيء وسقط
                # على هذي وحدها **بفارق قريب** يُذكَر في ذيل التنبيه بلا أن يُعَدّ مطابقًا.
                # (السبب: HTCR عند فيصل صعد **+23%** والحدّ المنصوص **20%** — فكان
                # يُرفَض بصمت وهو سهمٌ يعرضه فيصل إيجابيًّا. العتبة **لا تُمَسّ**.)
                _rp = pr.get("rose_pct")
                if (_rp is not None
                        and _rp <= CONFIG["SPLIT_ROSE_MAX_PCT"]
                        * float(CONFIG["SPLIT_ROSE_NEAR_MULT"])):
                    near_miss.append({"symbol": sym, "rose_pct": _rp,
                                      "half": pr["half"], "ref": pr["ref"],
                                      "price": pr["price"],
                                      "event_kind": pr.get("event_kind", "split")})
                continue
            flt = ff(sym)                                        # ④ فلوت<2م (ياهو)
            if not (flt is not None and flt < CONFIG["SPLIT_RADAR_FLOAT_MAX"]):
                continue
            pump = fp(df) or {}                                  # ⑤ خالٍ من قروب
            if pump.get("found"):
                continue
            bor = {}                                             # السياق (أفضل-جهد)
            try:
                bor = fb(sym) or {}
            except Exception:
                bor = {}
            close = df["Close"]
            out.append({
                "symbol": sym, "price": pr["price"], "half": pr["half"],
                # 🥇 خطة فيصل التنفيذية (تحرر/أهداف بنيوية/فجوة/سحب سيولة) — عرض فقط
                "plan": faisal_split_plan(df, pr["price"]),
                "bottom_test": bottom_test_state(df),   # 🔁 «القاع 2» (فيصل EDBL)
                # 📏 متوسط 30ي من **تاريخ التقسيم** (فيصل LABT IMG_0303) — عرض/سياق
                "split_ma": split_ma_maturity(df, pr.get("split_date")),
                # 📏 مجموعة فيصل 20/30/50 من تاريخ التقسيم (30 LABT · 40 JEM · 50)
                "split_ma_set": split_ma_lines(df, pr.get("split_date")),
                # 🎯 «أهداف الشورت»: القاع التالي بنسبة السهم نفسه (فيصل TG_2041)
                "next_bottom": next_bottom_by_own_drop(df),
                "ref": pr["ref"], "split_date": pr["split_date"],
                # 🆕 نوع الحدث المؤسِّس (قسم/طرح جديد) + نموذجه — عرض/سياق
                "event_kind": pr.get("event_kind", "split"),
                "event_form": pr.get("event_form"),
                "freq": pr.get("freq"), "float": flt,
                "avail": bor.get("shares_available"),
                "borrow_fee": bor.get("borrow_fee"),
                "ema20": round(ema(close, 20), 3),
                "ema30": round(ema(close, 30), 3),
                "ema50": round(ema(close, 50), 3),
            })
        except Exception:
            continue
    out.sort(key=lambda x: x.get("float") or 0)   # الأصغر فلوتًا أولًا (أندر = أقوى)
    # 🔔 القريبون من شرط «لم يصعد»: **يُسجَّلون دائمًا** (لا قصّ صامت) ويُذكرون في ذيل
    # التنبيه لو أُرسِل — ولا يُنشئون رسالة وحدهم (عقد المستخدم: «المطابق الكامل فقط»).
    _SPLIT_NEAR_MISS[:] = sorted(near_miss, key=lambda x: x["rose_pct"])[:6]
    if _SPLIT_NEAR_MISS:
        log("🔔 قريبون من شرط «لم يصعد» (لم يُعَدّوا مطابقين): " + " · ".join(
            f"{n['symbol']} صعد {n['rose_pct']:.0f}%" for n in _SPLIT_NEAR_MISS))
    return out


# ══════════════════════════════════════════════════════════════════════════
# ⓿-د خطة فيصل **النموذجية** لسهم المقسّم (صورتا $NUWE: IMG_0413 + IMG_0414)
# ══════════════════════════════════════════════════════════════════════════
# **المصدر (فُتحت الصورتان بالعين):** خطة فيصل الحيّة على NUWE **قبل انفجاره** والسعر
# 1.80-1.95 — وهدفُها الأول تحقّق بالحرف (الانفجار بلغ ~3.8 = +100%). نصّه:
#   IMG_0414: «دق القاع الجمعه **1.80** · عنده فجوه من … · الهدف الاول **شمعه التقسيم
#              3.81** · هدف ثاني … **شمعة الفجوه الساقطه** · الهدف الثالث … **راس شمعة
#              الفجوه الساقطه** · اما **يشده جميع** ل … او **يلعب موجات**»
#   IMG_0413: «هذي اهداف السهم · **الشرط الان ثبات 1.95 · عدم كسر 1.83**»
#   ومستويات شارته: 3.812 🔵 · 5.216 · 7.368 ⚫ · 2.050 🔴 · 14.010.
# **الفجوة بين كرتنا وخطّته** كانت: القيمة `_split_day_value` محسوبة عندنا وتُستعمل
# لشرط «لم يصعد» فقط (لا تُعرض هدفًا) · والفجوة تُعرض **مدًى** لا **شمعةً** · ولا شرط
# تنفيذيّ مزدوج ولا حدث قاعٍ بتاريخه ولا سيناريوهات.
# 🔒 **عرضٌ حصرًا**: الشروط الستّة والعضوية والترتيب **بتٌّ بتّ** (قفل توصيف يثبته:
# نفس المطابقين مجموعةً وترتيبًا مع الإثراء وبدونه) · كل الدوال نقيّة/فاشلة-آمنة →
# غياب البيانات يُسقط الأسطر **بصمتٍ لا بكذب** · خارج الفرز والجذور نهائيًّا.
def _plan_px(v) -> str:
    """صيغة سعر خطة فيصل **بحرفيّة أرقامه**: منزلتان عادةً، وثالثة لو كانت غير صفرية
    (‏3.81 · 5.216 · 7.368 · 1.95 · 1.83 — كما كتبها ورسمتها شارته). بقية الكرت تبقى
    على منزلتين كما هي. نقيّة · فاشلة-آمنة → "" (**تعذّر ≠ صفر** · **NaN ليس None**)."""
    try:
        f = float(v)
    except (TypeError, ValueError):
        return ""
    if f != f or f in (float("inf"), float("-inf")):     # ⚠️ NaN/لانهاية ليست None
        return ""
    s = f"{f:.3f}"
    return s[:-1] if s.endswith("0") else s


def falling_gap_candle(df, price=None, lookback=None):
    """🕳️ **شمعة الفجوة الساقطة** (فيصل، خطة NUWE `IMG_0414`): «هدف ثاني **شمعة الفجوه
    الساقطه** · الهدف الثالث **راس شمعة الفجوه الساقطه**» = الشمعة التي **خلّفت** أقرب
    فجوة هابطة غير مملوءة فوق السعر. **قيمتها** (الإغلاق — «قيمة الشمعة» بمفردات فيصل
    الموثّقة في `_split_day_value`) هدفٌ، و**رأسها** (High) هدفٌ أعلى وهو حافة الفراغ.

    الكشف **مُفوَّض** لتعريف البيت الواحد `unfilled_gaps_above` (فجوة **هابطة** حصرًا:
    قمة الشمعة تحت قاع سابقتها · حجمها ≥ `GAP_MIN_PCT` · فوق السعر · غير مملوءة) فلا
    يتفرّق التعريف بين موضعين؛ ثم نستعيد **الشمعة نفسها** من `ago` **ونُعيد فحص اتجاه
    الفجوة بأنفسنا** — حارسٌ ضدّ انزياح الفهرس أو تبدّل التعريف: **فجوة صاعدة ⇒ None**.

    يرجع {value, head, gap_bottom, gap_top, date, ago} أو **None**. نقيّة · فاشلة-آمنة
    · بلا نظر مستقبلي (الفجوة من شموعٍ مضت). عرض/سياق فقط — خارج الفرز والجذور."""
    try:
        if df is None or len(df) < 2:
            return None
        lb = int(lookback if lookback is not None
                 else CONFIG["GAP_ABOVE_LOOKBACK_D"])
        z = (unfilled_gaps_above(df, lb) or {}).get("nearest")
        if not z:
            return None
        n = len(df)
        i = n - 1 - int(z.get("ago", -1))
        if not (1 <= i < n):
            return None
        h = df["High"].values.astype(float)
        lo = df["Low"].values.astype(float)
        c = df["Close"].values.astype(float)
        head, val, prev_low = float(h[i]), float(c[i]), float(lo[i - 1])
        # 🔒 اتجاه الفجوة **هابط حصرًا** (رأس الشمعة تحت قاع سابقتها). الصاعدة ليست
        # «شمعة فجوة ساقطة» فلا تُقبل — وهذا الفحص يملكه هذا الموضع لا المُفوَّض إليه.
        if not (head > 0 and prev_low > 0 and head < prev_low):
            return None
        p = float(price) if price is not None else float(c[-1])
        if p != p or head <= p:            # لا بدّ أن تكون فوق السعر (هدفًا لا تاريخًا)
            return None
        if val != val or head != head or val <= 0:      # ⚠️ NaN ليس None
            return None
        try:
            d = str(pd.Timestamp(df.index[i]).date())
        except Exception:
            d = None
        return {"value": val, "head": head, "gap_bottom": head,
                "gap_top": prev_low, "date": d, "ago": int(n - 1 - i)}
    except Exception:
        return None


def bottom_strike(df, lookback=None):
    """🕳️ **حدث «دقّ القاع» بتاريخه** (فيصل NUWE: «دقّ القاع **الجمعه 1.80**») — كان
    عندنا شرطًا داخليًّا صامتًا («حافظ 3ج») بلا إعلانٍ للقارئ. = أدنى `Low` داخل **نفس
    نافذة** `SPLIT_BOTTOM_LOOKBACK` التي يبني عليها `faisal_split_plan` حقلَ `bottom`
    (فلا يتناقض رقمان في كرتٍ واحد) **مع تاريخه**. يرجع {price, date} أو None.
    نقيّة · فاشلة-آمنة · عرض/سياق فقط."""
    try:
        if df is None or len(df) < 1:
            return None
        lb = int(lookback if lookback is not None
                 else CONFIG["SPLIT_BOTTOM_LOOKBACK"])
        tail = df["Low"].tail(max(1, lb)).dropna()
        if len(tail) == 0:
            return None
        v = float(tail.min())
        if v != v or v <= 0:                             # ⚠️ NaN ليس None
            return None
        try:
            d = str(pd.Timestamp(tail.idxmin()).date())
        except Exception:
            d = None
        return {"price": v, "date": d}
    except Exception:
        return None


def split_target_kind(price, resist=None, clean=None, tol: float = 0.015) -> str:
    """🎨 لون الهدف بمفتاح فيصل الموثّق (‏⚫ مقاومة تصدّى لها السعر · 🔵 هدفٌ بلا
    مقاومة = فراغ فوقه يطير له) — **نفس قاعدة `targets_kind` بالفارز حرفيًّا**
    (`analyze_ticker`: أولوية «النظيف» أولًا، ثم المقاومة، والافتراض 🔵 عند عدم
    المطابقة، بتسامح 1.5%). أُعيد استعمال القاعدة لا كتابتها من جديد.
    نقيّة · فاشلة-آمنة → "" عند سعرٍ تالف."""
    try:
        v = float(price)
    except (TypeError, ValueError):
        return ""
    if v != v or v <= 0:                                 # ⚠️ NaN ليس None
        return ""

    def _near(pool):
        for x in (pool or []):
            try:
                b = float(x)
            except (TypeError, ValueError):
                continue
            if b > 0 and abs(v / b - 1.0) <= tol:
                return True
        return False

    if _near(clean):
        return "🔵"
    return "⚫" if _near(resist) else "🔵"


def _model_levels(row, df, price, skip_clean=None):
    """مجموعتا اللون لخطة النموذج — **من نفس مصادر الفارز**: ⚫ = مقاومات سوينغ
    ورؤوس الشموع الحمرا (+ تحرر/أهداف الخطة البنيوية المحسوبة سلفًا) · 🔵 = قيعان
    الفجوات غير المملوءة (فراغ فوقها). ترجع (resist, clean). فاشلة-آمنة → قوائم.

    ⚠️ `skip_clean`: **منعُ دائرية**. رأس شمعة الفجوة الساقطة **هو نفسه** قاع تلك
    الفجوة، فلو تُرك في مجموعة «النظيف» لصار 🔵 **بحكم التعريف دائمًا** = لونٌ بلا
    معلومة. وهو في الحقيقة **حافّة** الفراغ لا فراغٌ: السعر تداول عنده وسقط منه
    (رأس شمعة حمراء = مقاومة بقاعدة فيصل) — ولهذا رسمه فيصل نفسه **أسود** في
    شارت NUWE (‏7.368 ⚫) بينما رسم شمعة التقسيم **أزرق** (‏3.812 🔵)."""
    resist, clean = [], []
    # ⚠️ خطةٌ تالفة (نصّ) ⇒ `.get` = AttributeError **لا يلتقطه** `except (TypeError,
    # ValueError)` أدناه ⇒ ينهار التنبيه كلّه. نوعٌ غير قاموس = غياب لا انهيار.
    p = row.get("plan") if isinstance(row, dict) else None
    p = p if isinstance(p, dict) else {}
    try:
        if p.get("liberation"):
            resist.append(float(p["liberation"]))
        for t in (p.get("targets") or []):
            resist.append(float(t.get("price")))
        if (p.get("gap") or {}).get("bottom"):
            clean.append(float(p["gap"]["bottom"]))
    except (TypeError, ValueError):
        pass
    if df is not None:
        try:
            resist += [float(x) for x in resistance_levels(df, price)]
        except Exception:
            pass
        try:
            resist += [float(x) for x in _red_candle_heads(df, price)]
        except Exception:
            pass
        try:
            for z in (unfilled_gaps_above(
                    df, int(CONFIG["GAP_ABOVE_LOOKBACK_D"])) or {}).get("zones") or []:
                clean.append(float(z["bottom"]))
        except Exception:
            pass
    if skip_clean:
        try:
            k = float(skip_clean)
            clean = [x for x in clean if not (k > 0 and abs(x / k - 1.0) <= 0.005)]
        except (TypeError, ValueError):
            pass
    return resist, clean


def faisal_model_plan(row, df=None, splits=None, resist=None, clean=None):
    """🥇 **خطة فيصل النموذجية** لصفّ صيّاد المقسّم (تركيبُ عرضٍ من حقولٍ محسوبة سلفًا
    — صفر معيارٍ جديد وصفر عتبةٍ مخترعة). ترجع:
      `targets` [{price,label,kind}] — ① **شمعة التقسيم** (`_split_day_value` **حصرًا**:
        هي مرجع فيصل «اقسم قيمة الشمعة» وتُحسب عندنا سلفًا لشرط «لم يصعد») ② **شمعة
        الفجوة الساقطة** (قيمتها) ③ **رأسها** — كلّها **فوق السعر** ومرتّبة تصاعديًّا.
      `hold_above` (=`liberation` الخطة: «ثبات فوق») · `no_break`/`bottom_date`
      (=`bottom_strike`: «عدم كسر» + «دقّ القاع يوم…») · `top` (أعلى مستوى معروف).

    ⚠️ الهدف ① **لأحداث التقسيم فقط**: صفّ «طرح جديد» لا شمعة تقسيمٍ له، فيُسقَط بدل
    أن يُلفَّق من تقسيمٍ قديمٍ غير ذي صلة. `resist`/`clean` حاقنان **للاختبار** فقط
    (نمط `faisal_split_plan` القائم) والإنتاج يشتقّهما من `df`.
    نقيّة · فاشلة-آمنة (أي عطل ⇒ مفاتيح فارغة) · عرض فقط — خارج الفرز والجذور."""
    out = {"targets": [], "hold_above": None, "no_break": None,
           "bottom_date": None, "top": None}
    try:
        r = row or {}
        price = float(r.get("price"))
        if price != price or price <= 0:                 # ⚠️ NaN ليس None
            return out
        # ⚠️ خطةٌ تالفة (نصّ/None) ⇒ `.get` عليها **AttributeError** يهدم التنبيه كلّه
        # ويضيّع المطابق. نوعٌ غير قاموس = غياب، لا انهيار.
        p = r.get("plan")
        p = p if isinstance(p, dict) else {}
        cand = []
        # ① شمعة التقسيم — **المصدر الوحيد** `_split_day_value` (قفل مصدر باختبار)
        if str(r.get("event_kind") or "split") == "split" and df is not None:
            try:
                v1 = _split_day_value(df["Close"], splits, df.index[-1])
            except Exception:
                v1 = None
            if v1 is not None and float(v1) == float(v1) and float(v1) > price:
                cand.append((float(v1), "شمعة التقسيم"))
        # ②③ شمعة الفجوة الساقطة: قيمتها ثم رأسها
        gc = falling_gap_candle(df, price) if df is not None else None
        if gc:
            if gc["value"] > price:
                cand.append((gc["value"], "شمعة الفجوة الساقطة"))
            if gc["head"] > price:
                cand.append((gc["head"], "رأس شمعة الفجوة الساقطة"))
        if resist is None or clean is None:
            _r, _c = _model_levels(r, df, price,
                                   skip_clean=(gc or {}).get("head"))
            resist = _r if resist is None else resist
            clean = _c if clean is None else clean
        seen = []
        for v, label in sorted(cand, key=lambda x: x[0]):
            if any(abs(v / s - 1.0) <= 0.005 for s in seen if s > 0):
                continue                     # لا تكرار لنفس المستوى بمسمّيين
            seen.append(v)
            out["targets"].append({"price": v, "label": label,
                                   "kind": split_target_kind(v, resist, clean)})
        out["hold_above"] = (float(p["liberation"])
                             if p.get("liberation") else None)
        bs = bottom_strike(df) if df is not None else None
        if bs:
            out["no_break"], out["bottom_date"] = bs["price"], bs["date"]
        elif p.get("bottom"):
            out["no_break"] = float(p["bottom"])
        # «القمة الكبرى» = أعلى مستوى معروف — **وتُحسب فقط إذا قام السلّم فعلًا**:
        # بلا سلّمٍ تصير سطرًا يعيد `ref` المعروض سلفًا مرّتين = ضجيجٌ لا معلومة.
        tops = [t["price"] for t in out["targets"]]
        if tops:
            try:
                if r.get("ref"):
                    tops.append(float(r["ref"]))
            except (TypeError, ValueError):
                pass
        out["top"] = max(tops) if tops else None
    except (TypeError, ValueError, KeyError):
        return out
    return out


def faisal_model_lines(mp) -> list:
    """أسطر خطة فيصل النموذجية للكرت (بلا بادئة مسافات — يضيفها المُنادي).
    ترتيبها ترتيبُ رسالته: **دقّ القاع** ← **الأهداف المسمّاة** ← **السيناريوهان**.
    غياب أي حقل ⇒ يسقط سطره وحده (فاشل-آمن، لا كذب ولا انهيار)."""
    out = []
    try:
        m = mp or {}
        if m.get("no_break") and m.get("bottom_date"):
            out.append(f"🕳️ دقّ القاع يوم {esc(m['bottom_date'])} عند "
                       f"<b>${_plan_px(m['no_break'])}</b>")
        for i, t in enumerate(m.get("targets") or [], 1):
            out.append(f"🎯 الهدف {i} — {esc(t['label'])}: {t.get('kind') or ''} "
                       f"<b>${_plan_px(t['price'])}</b>")
        if m.get("top"):
            out.append(f"🌊 إمّا يشدّه إلى القمة الكبرى <b>${_plan_px(m['top'])}</b> "
                       "أو يلعب موجات (فيصل: «اما يشده جميع … او يلعب موجات»)")
        if m.get("targets"):
            # 🕵️ المايكرو في شارت فيصل (لقطة الطلب/العرض + FSTO(14,3)) **موجود عندنا
            # بفحص اليد** — ولا يُنقَل للكرت (قرار حجم الرسالة)، فتكفي الإحالة.
            out.append("🕵️ المايكرو (لقطة الطلب/العرض · FSTO): بأداة فحص اليد")
    except Exception:
        return out
    return out


def _hunter_history(syms):
    """جالب إطارات المطابقين **للعرض** — **نداء دفعة واحد** لكل الرموز (درس
    `plans/006`: النداء لكل رمز على حدة يخنق). المطابق الكامل نادرٌ بحكم التعريف
    (صفٌّ أو صفّان) فالتكلفة مهملة. أفضل-جهد: أي عطل ⇒ {} فتسقط أسطر الخطة
    **بصمتٍ لا بكذب**، ومعها سطر سجلٍّ صريح من المُنادي (يُعلَن ولا يُصمت)."""
    try:
        if yf is None or not syms:
            return {}
        return download_history(sorted(set(syms))) or {}
    except Exception:
        return {}


def _hunter_models(rows: list, fetch_hist=None, fetch_splits=None) -> dict:
    """يبني خطة النموذج لكل صفّ (رمز → خطة). الإطارات بنداءٍ **واحد** والتقسيمات
    لأصحاب الإطارات فقط. فاشل-آمن مطلق + **إعلانٌ عند النقص** (لا سقف صامت)."""
    syms = [str(r.get("symbol") or "") for r in (rows or []) if r.get("symbol")]
    try:
        fh = fetch_hist if fetch_hist is not None else _hunter_history
        hist = fh(syms) or {}
    except Exception:
        hist = {}
    if not isinstance(hist, dict):     # جالبٌ يرجع نوعًا آخر ⇒ غياب لا انهيار
        hist = {}
    fs = fetch_splits if fetch_splits is not None else _fetch_splits
    out, missing = {}, []
    for r in (rows or []):
        sym = str(r.get("symbol") or "")
        df = hist.get(sym)
        if df is None:
            missing.append(sym)
        sp = None
        if df is not None:
            try:
                sp = fs(sym)
            except Exception:
                sp = None
        out[sym] = faisal_model_plan(r, df=df, splits=sp)
    if missing:
        log("🥇 خطة فيصل النموذجية: تعذّر جلب إطار لـ"
            f"{len(missing)} رمز ({' · '.join(missing[:6])}) — "
            "تُعرض الأسطر المتاحة فقط (لا تخمين).")
    return out


# ═══════════════ 🔬 أداة «النهج العلمي» (فيصل · UPC) — مستقلّة ═══════════════
# 🔒 **أداةٌ مستقلّة تمامًا عن فارز الارتكاز (14 بوّابة) وعن صيّاد المقسّم** — على
# نمط الصيّاد حرفيًّا (قرار المالك 2026-08-01). مصدرُها `FAISAL_SCIENTIFIC_METHOD.md`
# (ستّ صور UPC) **+ ما كان عندنا ولم يُستغَلّ**: `trigger_state` وسندُها `TG_1870`.
# ⚖️ وميزتُها الحاسمة على القياس التاريخيّ: الشرطان اللذان **استحال باكتيستُهما**
# (لا إعلان طرح · شورت قليل ورسوم عالية) **يعملان حيًّا** ⇒ تُطبَّق الوصفة **كاملة**.

def peak_and_decline(high):
    """📈 قمّةٌ حديثة ثم هبوط — يرجّع `{peak_idx, bars_since_peak, peak, rise_pct}`.

    🔴 **ولا تُستعمل `behavior_rise_profile.recency_bars` مكانها**: تُحسب على
    `c[:n-BASE_WINDOW]` ⇒ **مُزاحةٌ 15 جلسة**، فتقلب الحكم على شرط «20 < 30 يوم».
    `rise_pct` = صعودُ القمّة عن **أدنى قمّةٍ سبقتها داخل النافذة** (المصفوفة
    المُمرَّرة `High` وحدها) — ⚠️ **لا عن أدنى قاع**؛ صُحّح الوصف 2026-08-01 بعد أن
    كان يقول «قاع» والكودُ يقرأ القمم (تُقرأ القيمة **بخسًا طفيفًا** لا نفخًا).
    نقيّة · فاشلة-آمنة → None."""
    try:
        h = np.asarray(high, dtype=float)
    except Exception:                                            # noqa: BLE001
        return None
    if h.size < 5 or not np.isfinite(h).any():
        return None
    pk = int(np.nanargmax(h))
    if pk <= 0:
        return None
    pre = h[:pk]
    base = float(np.nanmin(pre)) if pre.size else None
    if not base or base <= 0:
        return None
    return {"peak_idx": pk, "bars_since_peak": int(h.size - 1 - pk),
            "peak": float(h[pk]), "rise_pct": (float(h[pk]) / base - 1.0) * 100.0}


def method_founding(df, rise_min=None, win_bars=None, dmin=None, dmax=None,
                    stats=None):
    """🏛️ **الحدث المؤسِّس** (`IMG_0486`/`IMG_0489`): «سهم صاعد **نسبه عاليه**» ثم
    «تنتظر هبوطه فترة زمنيه · **20 < 30 يوم**».

    العتبات: الصعود من `EXPLOSION_PCT` والنافذة من `PRIOR_SPIKE_WINDOW` — **ثوابت
    إنتاجية قائمة لا أرقامٌ مُبتكَرة**؛ و`20/30` **حرفيّان من الصورة**.

    ⚠️ **وحدُّ صدقٍ يُقاس ولا يُدفَن (‏قرار المالك «امش على اللي متأكد منه»،
    2026-08-01):** «‏20 < 30 يوم» **منصوصٌ حرفيًّا**، أمّا حدُّ الصعود فنصُّه «سهم
    صاعد **نسبه عاليه**» **بلا رقم** ⇒ الرقم 50% **اشتقاقُنا** (موسومٌ
    `faisal_inferred` في `FAISAL_SOURCE_LEDGER.md`). فلا يُغيَّر بالرأي — لكن
    `stats` (قاموسٌ اختياريّ) يُحصي **كم مرشّحًا استوفى النافذة وسقط على الحدّ
    وحده** فيصير قرارُ معايرته لاحقًا **برقمٍ مقيس لا بتخمين**.
    🔒 `stats=None` (الافتراضيّ) ⇒ **السلوك السابق حرفيًّا** والقرار لا يتغيّر أبدًا.
    نقيّة · فاشلة-آمنة → None."""
    rise_min = float(CONFIG["EXPLOSION_PCT"] if rise_min is None else rise_min)
    win_bars = int(CONFIG["PRIOR_SPIKE_WINDOW"] if win_bars is None else win_bars)
    dmin = int(CONFIG["METHOD_DECLINE_MIN"] if dmin is None else dmin)
    dmax = int(CONFIG["METHOD_DECLINE_MAX"] if dmax is None else dmax)
    try:
        pd_ = peak_and_decline(df.tail(win_bars + dmax + 5)["High"]
                               .astype(float).values)
    except Exception:                                            # noqa: BLE001
        return None
    if not pd_:
        return None
    in_win = bool(dmin <= pd_["bars_since_peak"] <= dmax)
    if stats is not None and in_win:                 # 🩺 إحصاءٌ لا قرار
        stats["window_ok"] = stats.get("window_ok", 0) + 1
        if pd_["rise_pct"] < rise_min:
            stats["rise_only_fail"] = stats.get("rise_only_fail", 0) + 1
    if pd_["rise_pct"] < rise_min or not in_win:
        return None
    return pd_


def method_sequence(df, win, bounce_min=None, tol=None):
    """🪜 **التسلسل الرباعيّ بقراءة «الثبات»** — `IMG_0486`/`IMG_0488` حرفيًّا:

    > «صعد بعد اختبار الدعم السابق قبل صعوده كان 3.10 · **هبط واختبر 3.10 حافظ
    > عليها** صعد 17٪ · الصعود غالبا من **10 > 15٪** · **يرجع يهبط يختبر الدعم** ·
    > هنا يكون الدخول عند اقل سعر 3.20 مع وقف 3»

    وشاهدُها البصريّ في `IMG_0488`: «**ذيول شموع وعدم كسرها**» — خطٌّ أحمر تلمسه
    الذيول ولا تخترقه.

    🔴🔴 **ولماذا لا تُستعمل `trigger_state` هنا — وهو خطأٌ وقعتُ فيه وصحّحه المالك:**
    مرحلتُها ③ سندُها `TG_1870` «رجوعٌ يختبر القاع **مع سحب سيولة**» وتشترط **كسر**
    القاع بـ7-13% ثم استعادته. وهذا **نقيضُ** ما تصفه هذي الصور («حافظ عليها» ·
    «وعدم كسرها») ⇒ السهمُ الذي يفعل ما يصفه فيصل **يسقط** على `trigger_state`
    بنيويًّا. المصدران قراءتان مختلفتان لسهمين مختلفين، وخلطُهما كان يُفرغ الأداة.
    (‏`trigger_state` **لم تُمَسّ** — تبقى لقراءتها ولتجربة `candle_readiness`.)

    الشروط على آخر `win` بارًا، **بترتيبٍ زمنيّ**:
      ① **قاعٌ مكوَّن** `b` = الأدنى حتى لحظته.
      ② **اختبار مقاومة**: أعلى قمّةٍ بعده ترتفع ≥`bounce_min`% عنه (الحدّ **10%**
         منصوصٌ، والصور تُظهر 15% و17%).
      ③ **رجوعٌ يختبر القاع**: أدنى قاعٍ بعد القمّة يعود إلى نطاق `tol` من القاع.
      ④ **وثبات**: لا يهبط تحته أكثر من `tol` **ولا يُغلق تحته إغلاقًا واحدًا**.
    يرجّع `{ok, bottom, peak, bounce_pct, retest_low, undercut_pct, touches}` أو
    `None`. **نقيّة · بلا نظر مستقبليّ** (لا تقرأ إلا `df` المُمرَّر) · فاشلة-آمنة.
    🔒 **لا `RSI` هنا**: الصور الستّ تعدّد شروطها (لا طرح · لا قروب · شورت قليل ورسوم
    عالية · سلامة من الحراج) و**ليس فيها `RSI`** — فإقحامُه بوّابةً كان زيادةً منّي."""
    bounce_min = float(CONFIG["METHOD_BOUNCE_MIN_PCT"] if bounce_min is None
                       else bounce_min)
    tol = float(CONFIG["METHOD_HOLD_TOL"] if tol is None else tol)
    try:
        w = df.tail(int(win))
        lo = w["Low"].astype(float).values
        hi = w["High"].astype(float).values
        cl = w["Close"].astype(float).values
    except Exception:                                            # noqa: BLE001
        return None
    n = len(lo)
    if n < 6 or not (np.isfinite(lo).all() and np.isfinite(hi).all()
                     and np.isfinite(cl).all()):
        return None
    for b in range(0, n - 3):
        bot = float(lo[b])
        if bot <= 0 or float(np.min(lo[:b + 1])) < bot:
            continue                          # ① قاعٌ مكوَّن = الأدنى حتى لحظته
        pk = b + 1 + int(np.argmax(hi[b + 1:]))
        if pk >= n - 1:                       # لا بدّ من بارٍ **بعد** القمّة للرجوع
            continue
        if (float(hi[pk]) / bot - 1.0) * 100.0 < bounce_min:
            continue                          # ② اختبار مقاومة بصعودٍ ≥ الحدّ
        rl = float(np.min(lo[pk + 1:]))
        if rl > bot * (1.0 + tol):
            continue                          # ③ لم يرجع ليختبر القاع أصلًا
        if rl < bot * (1.0 - tol):
            continue                          # ④ كسرَه ⇒ **مسحٌ لا ثبات** ⇒ يُرفض
        # «ولا كسرها» — إغلاقٌ واحد تحت القاع يُبطل الثبات. (وليس تحصيلَ حاصل:
        # قاعٌ داخل `tol` تحت المستوى قد يُغلق تحته وهو ما نرفضه هنا.)
        if any(float(cl[k]) < bot for k in range(b + 1, n)):
            continue
        hits = [abs(float(lo[k]) / bot - 1.0) <= tol for k in range(b, n)]
        touches = sum(1 for k, v in enumerate(hits) if v and not (k and hits[k - 1]))
        return {"ok": True, "bottom": bot, "bottom_idx": b, "peak": float(hi[pk]),
                "bounce_pct": round((float(hi[pk]) / bot - 1.0) * 100.0, 1),
                "retest_low": rl, "undercut_pct": round((1.0 - rl / bot) * 100.0, 2),
                "touches": int(touches)}
    return None


_METHOD_NEAR = []          # 🔭 «قريبون من الشرط» — يُملأ بكل مسح (تتبّعٌ حيّ)
# 🔬 رموزُ مَن استوفى **الحدث المؤسِّس** (‏الحدث تقويميّ ⇒ **مستقلٌّ عن الفريم**).
#    يُملأ بكل مسح ولا يُستعمَل في أي قرار — مادّةُ مِجَسّ الفريم وحده (‏§الفريم).
_METHOD_FOUNDING = []
# 🩺 عدّاداتُ آخر مسح — تُنشَر ليقرأها المِجَسّ والتشخيص **بالرقم الحقيقيّ**.
# 🐞 وسببُها عيبٌ في كودي: كان المِجَسّ يقارن 4س بـ`len(_METHOD_NEAR)` وهي
#    **عددُ القريبين لا عددُ مَن بلغ التسلسل** — يتساويان **فقط** حين لا مطابق
#    كامل. فأوّلُ يومٍ يُنتج مطابقًا كانت المقارنة ستُطبَع **مبخوسة بصمت**.
_METHOD_STAGE = {}
# كم يُعرَض منهم — **وما زاد يُعلَن عددُه لا يُقصّ صامتًا**.
# 🔴 **رُفِع 10 ⟶ 25 (2026-08-01، بسؤال المالك «فيه أسهم بالقديمة مب بالجديدة»):**
# القائمة **مسقوفةٌ طبيعيًّا** بمَن يبلغ التسلسل الرباعيّ (‏14 يوم 07-31 من 3386
# رمزًا) ⇒ سقفُ 10 كان **أضيق من العدد المعتاد** فيقصّ كلَّ يومٍ تقريبًا. و25
